(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-rectified-flow-sampler"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-1\">一 · 事故现场：当 8 步出图把文字渲染成乱码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-2\">二 · 它到底改了什么：从弯曲路径到恒定速度场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-3\">三 · 系统代价账：步数、前向次数与显存带宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-4\">四 · 适用边界：直线假设在哪里失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-5\">五 · 失败模式清单与工程兜底</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-6\">六 · 从一次 8 步出图的线上事故说起：整流流采样器到底治什么病</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-7\">七 · 从请求到第一个 latent：入口与时间网格</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-8\">八 · 单步速度场前向：DiT 主体与条件注入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-9\">九 · Euler 更新：一步一前向的代价结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-10\">十 · 二阶中点法：两次前向换精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-11\">十一 · 末端 latent 交付与 VAE 解码的衔接</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-12\">十二 · 步骤顺序里的调度与复用判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-13\">十三 · 边界条件：直线假设失效与二阶积分的真实开销</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-14\">十四 · 直线插值的逐项解剖：为什么 t 的系数决定误差阶</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-15\">十五 · 损失函数的期望结构与梯度含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-16\">十六 · Euler 与中点法的可实现伪代码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-17\">十七 · 时间网格与步长的工程取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-18\">十八 · 与 CFG、少步蒸馏叠加时的公式变形</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-19\">十九 · 失败模式的公式定位与回退策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-20\">二十 · 直线假设的裂缝：失效条件、二阶代价与可落地的伪代码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-21\">二十一 · 请求形态：单次 latent 生成才是它的主场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-22\">二十二 · 长度分布：步数是唯一的“序列长度”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-23\">二十三 · 并发与批大小：批内并行、步间串行的调度约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-24\">二十四 · 负载不对时：三种可观测的崩坏</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-25\">二十五 · 配方边界：什么时候该换算法而不是调参</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-26\">二十六 · 把配方写成可执行的准入规则</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-27\">二十七 · 负载配方：直线采样器吃什么样的请求，不吃什么样的</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-28\">二十八 · 硬件档位与并行拓扑的切分点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-29\">二十九 · 量化方案的叠加顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-30\">三十 · KV 策略：latent 缓存与条件缓存的分账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-31\">三十一 · 调度参数：步数、批、引导系数的三角约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-32\">三十二 · 一个可复现的配置思路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-33\">三十三 · 配方边界：直线假设失效处，就是配置要回退的地方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-34\">三十四 · 单图时延的构成：步数乘以每步前向，再乘以批的空转</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-35\">三十五 · 显存与带宽：latent 缓存、timestep embedding 与权重驻留</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-36\">三十六 · 通信：张量并行下的每步 all-reduce 与分离式部署的 latent 搬运</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-37\">三十七 · 功耗与热：少步高批把能量密度推到峰值区间</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-38\">三十八 · 尾延迟：步长过大导致的回退与重采样</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-39\">三十九 · 规模上限的排序：带宽、功耗、通信、调度的先后</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-40\">四十 · 规模上升后的首个瓶颈：从算力墙到带宽墙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-41\">四十一 · 尾延迟与失效条件：少步把误差集中到末端</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-42\">四十二 · 精度失效的三条路径与定位手段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-43\">四十三 · OOM 的真实来源与回收顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-44\">四十四 · 批抖动与路由不均的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-45\">四十五 · 尾延迟尖刺的四个来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-46\">四十六 · 监控埋点与回滚的工程约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-47\">四十七 · 直线采样器的失效边界与在线诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-48\">四十八 · 同族谱系与选型的第一性判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-49\">四十九 · 决策表：四类负载的映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-50\">五十 · 与一致性模型的边界：蒸馏 vs 重参数化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-51\">五十一 · 与 DDIM 的边界：scheduler 复用性的工程价值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-52\">五十二 · 组合选型的三个工程约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-53\">五十三 · 适用条件的形式化与规模上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rectified-flow-sampler-sec-54\">五十四 · 同族算法选型：整流流、DDIM 与一致性模型的边界判据</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:493px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 493.2 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"411.2\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">训练时在 x0 与噪声间做直线插值 x_t=(1−t)x0+t·ε，回归速…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"411.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">推理从纯噪声出发，按离散时间点 t_k 计算速度场</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"411.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用 Euler 或二阶中点法沿直线更新 x_{k+1}=x_k+Δv</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"411.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">少步（4–8 步）即可收敛，末端 latent 送 VAE</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"411.2\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">可叠加 CFG 与少步蒸馏进一步压步数</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-rectified-flow-sampler-sec-1\">一 · 事故现场：当 8 步出图把文字渲染成乱码</h3>\n<p>某条线上文生图服务在扩容时把采样步数从 20 压到 8，压测阶段一切正常，直到真实流量里出现带文字的海报类请求：招牌上的字母被拉成互相粘连的笔画，多物体场景里两只手合成一只。事故复盘时发现，问题不在量化、不在批调度，而在采样器本身——DDIM 的 scheduler 与特定模型权重绑定，团队为了提速换了一个第三方少步 scheduler，概率路径的弯曲程度与模型训练时的假设不匹配，步长一大，离散化误差沿轨迹累积，末端 latent 分布已经偏移，VAE 只是忠实地把偏移解码成色块与错位结构。</p>\n<p>这类事故的代价是可量化的：单图时延被 SLO 压在 8 步以内，回退到 20 步意味着单卡吞吐按步数比例下降，扩容预算直接翻倍；若改用二阶积分补偿精度，每步两次前向又吃掉一半收益。工程上真正需要的不是“再调调 scheduler 参数”，而是一种把轨迹本身拉直、让大步长积分天然误差小的参数化方式。整流流（rectified flow）解决的正是这个具体问题：它不解决量化误差、不解决 VAE 解码瓶颈、也不解决批调度碎片化，它只把“少步离散化误差大”这一项从根上削掉。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-2\">二 · 它到底改了什么：从弯曲路径到恒定速度场</h3>\n<p>DDPM/DDIM 的采样轨迹是弯曲的：从纯噪声到样本的路径在概率空间中绕行，Euler 离散化每一步都引入与曲率成正比的截断误差，步数一少，误差不再是小量。整流流把训练期的插值方式换掉：取真实样本 $x_0$ 与高斯噪声 $\\varepsilon$，在 $t\\in[0,1]$ 上做直线插值，令网络回归从样本指向噪声的恒定速度场，监督目标就是噪声减样本。核心公式为：</p>\n<div class=\"formula\">$$x_t=(1-t)\\,x_0+t\\,\\varepsilon,\\qquad \\mathcal{L}=\\mathbb{E}\\big\\|v_\\theta(x_t,t)-(\\varepsilon-x_0)\\big\\|^2$$</div>\n<p>因为速度沿直线恒定，积分误差随步长线性增长而非高阶累积，这是“大步长也能用”的全部依据。推理阶段从纯噪声 $x_1$ 出发，按离散时间点 $t_k$ 前向计算速度场，Euler 更新为 $x_{k+1}=x_k+\\Delta t\\,v_\\theta(x_k,t_k)$；二阶中点法先取半步预测再校正，单步两次前向。末端 latent 直接送 VAE 解码。注意这里的边界：直线假设是对概率路径的重参数化，不是对数据分布的精确刻画，复杂条件下路径仍会偏离直线，这正是后面要划的适用边界。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-3\">三 · 系统代价账：步数、前向次数与显存带宽</h3>\n<p>把 20 步压到 8 步，收益不是线性的 2.5 倍，因为每步开销随批大小与分辨率变化。Euler 单步一次 DiT 前向，中点法单步两次，若不做 CFG 批合并，单图时延反而高于 Euler 大步长配置——这是二阶积分最容易被忽略的代价。以 Blackwell 单卡或张量并行覆盖 DiT 主体为例，单步前向的耗时由主体 GEMM 与注意力主导，可叠加 FP8/NVFP4 量化压缩计算与权重带宽；latent 与 timestep embedding 缓存按 batch 与分辨率线性增长，8 步配置下这部分显存占用远小于 20 步配置的中间激活峰值，但批大小在 1–8 间取值时，小 batch 的 kernel 利用率下降会抵消部分步数收益。</p>\n<table class=\"mini\"><thead><tr><th>配置</th><th>每步前向</th><th>总前向次数</th><th>主要代价</th></tr></thead><tbody><tr><td>DDIM 20 步</td><td>1（含 CFG 则 2）</td><td>20–40</td><td>时延高，吞吐受步数线性压制</td></tr><tr><td>整流流 Euler 8 步</td><td>1（CFG 合并为 1 批）</td><td>8</td><td>少步细节损失，复杂条件需回退</td></tr><tr><td>整流流中点法 8 步</td><td>2</td><td>16</td><td>单步成本翻倍，需批合并摊薄</td></tr></tbody></table>\n<p>工程判断落在“步数 × 每步前向次数”的乘积上，而不是单看步数。CFG 批合并把条件与非条件前向拼成一个 batch，是把中点法从亏损拉回持平的关键手段；引导系数在少步下过大易过饱和，需按步数重调，否则色彩崩坏会被误判为采样器失效。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-4\">四 · 适用边界：直线假设在哪里失效</h3>\n<p>直线假设在多物体、文字渲染等强约束条件下不严格成立：条件分布把概率路径推弯，8 步内速度场无法把弯曲部分积分到位，细节丢失表现为文字笔画粘连、物体边界错位。此时正确的工程动作不是继续压步数，而是回退到更多步或叠加少步蒸馏补偿。规模上，超高分辨率与强文本约束同样需要更多步，直线参数化本身不提供分辨率无关性。</p>\n<ul>\n<li>适合：4–8 步快速出图、需要 scheduler 跨模型复用的多模型服务池；速度场形式统一，换模型不必重训 scheduler。</li>\n<li>不适合：把采样器当作画质万能药——量化误差、VAE 解码瓶颈、批调度碎片化它都不管；强文本约束场景需蒸馏或更多步兜底。</li>\n<li>与一致性模型的边界：整流流是训练期重参数化路径，不依赖教师模型，可与少步蒸馏叠加进一步压步数；一致性模型靠蒸馏把多步压成一步，二者可组合而非互斥。</li>\n</ul>\n<p>一个具体例子：服务池里同时挂着两个 DiT 权重，DDIM 方案要为每个权重维护绑定 scheduler，扩容时配置漂移直接引发前述事故；换成整流流后统一速度场参数化，scheduler 跨模型复用，工程实现简化为“时间点网格 + Euler 更新”两件事，配置面收敛，事故面随之收敛。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-5\">五 · 失败模式清单与工程兜底</h3>\n<p>第一类失败是少步下多物体与文字场景细节丢失、直线假设不成立导致结构错位，兜底策略是按请求类型分流：强文本约束请求走更多步或蒸馏模型，普通请求走 8 步 Euler。第二类是二阶中点法每步两次前向，若不加批合并，单图时延反而高于 Euler 大步长配置，兜底是把 CFG 条件与非条件前向拼批，并只在画质敏感档位启用中点法。第三类是 CFG 系数在少步下过大引起过饱和与色彩崩坏，兜底是按步数重调引导强度，把引导系数作为步数的函数而非固定常数。第四类是步长过大时末端 latent 分布偏移，VAE 解码出现色块，兜底是监控末端 latent 的统计量偏移，触发步数回退。</p>\n<p>这些兜底共同指向一个工程判断：整流流把“少步离散化误差”这一项从算法层削掉，但它把复杂度转移到了请求分流与引导系数调度上。部署时应在服务入口按提示词复杂度与分辨率打标，把 8 步 Euler 作为默认档、中点法作为画质档、更多步作为兜底档，三档共享同一套速度场参数化，scheduler 不再与权重绑定——这正是它相对 DDIM 的核心工程价值，也是这条事故链被切断的位置。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-6\">六 · 从一次 8 步出图的线上事故说起：整流流采样器到底治什么病</h3>\n<p>某文生图服务把默认采样步数从 20 步压到 8 步以压住单图时延，上线后监控出现两类互不相干的告警：一是多物体提示词（两只动物、三个人物）的成图出现主体粘连与结构错位，二是带文字的提示词出现笔画糊化。回滚到 20 步后画质恢复，但单图时延回到不可接受的水平，SLO 直接击穿。根因不在模型权重，也不在 VAE，而在采样器：DDPM/DDIM 的概率路径是弯曲的，离散化误差随步长非线性累积，步数一降，误差就从“可接受”跳到“崩坏”。整流流（rectified flow）针对的正是这一个具体问题——把弯曲路径拉直，让大步长积分的误差随步长线性增长而非高阶累积，从而在 4–8 步量级维持画质。它不解决模型容量不足、不解决文本编码器对齐差、不解决 VAE 解码器本身的重建损失；把这三类问题误当作采样步数问题去压步，只会得到更快的坏图。</p>\n<p>机制上，训练期做的是路径重参数化而非蒸馏：取真实样本 $x_0$ 与高斯噪声 $\\varepsilon$，在 $t\\in[0,1]$ 上直线插值 $x_t=(1-t)x_0+t\\varepsilon$，令网络回归从样本指向噪声的恒定速度场，监督目标为 $v=x_1-x_0=\\varepsilon-x_0$。推理从纯噪声 $x_1$ 出发，按离散时间点前向计算 $v_\\theta(x_k,t_k)$，Euler 更新 $x_{k+1}=x_k+\\Delta t\\,v_\\theta(x_k,t_k)$；二阶中点法先取半步预测再校正，单步需两次前向。核心监督为</p>\n<div class=\"formula\">$$\\mathcal{L}=\\mathbb{E}\\big\\|v_\\theta(x_t,t)-(\\varepsilon-x_0)\\big\\|^2$$</div>\n<p>因为速度沿直线恒定，积分误差随步长线性而非高阶累积，这是“20 步压到 8 步”在机制上成立的原因，也是它与 DDIM 的分界：DDIM 的 scheduler 与特定模型绑定，换模型要重调；整流流用统一速度场参数化，scheduler 可跨模型复用，工程实现简单。但这条直线假设在复杂条件下不严格成立——多物体、文字渲染时真实概率路径仍有曲率，少步采样会把曲率抹平，表现为细节丢失与结构错位，这正是事故里那两类告警的来源。</p>\n<p>系统代价必须按“步数 × 每步开销”一起算，而不是只数步数。Euler 每步一次前向，中点法每步两次前向，若不做 CFG 批合并（把条件与非条件前向拼成一个 batch 摊薄开销），单图时延反而可能高于 Euler 大步长配置——步数少了，但每步贵一倍，账不一定划算。显存侧，latent 与 timestep embedding 缓存按 batch 与分辨率线性增长，批大小在 1–8 间按显存与 SLO 取；Blackwell（B200/GB200）上 DiT 主体可叠 FP8/NVFP4 GEMM 降单步成本，但量化误差与少步误差会叠加，需要联合验证而非分别验收。下表给出四种配置的取舍边界：</p>\n<table class=\"mini\"><thead><tr><th>配置</th><th>每步前向</th><th>典型步数</th><th>主要风险</th></tr></thead><tbody><tr><td>Euler + 大步长</td><td>1</td><td>4–8</td><td>步长过大时末端 latent 分布偏移，VAE 解码出色块或结构崩坏</td></tr><tr><td>中点法</td><td>2</td><td>4–8</td><td>单步成本翻倍，未批合并时单图时延反升</td></tr><tr><td>Euler + CFG 批合并</td><td>1（合并 batch）</td><td>8</td><td>CFG 系数在少步下过大引起过饱和与色彩崩坏，需按步数重调引导强度</td></tr><tr><td>整流流 + 少步蒸馏</td><td>1</td><td>更低</td><td>依赖蒸馏数据覆盖，强文本约束场景仍需回退步数</td></tr></tbody></table>\n<p>适用边界因此可以写得很硬：它适合 4–8 步快速出图与跨模型复用 scheduler 的场景，适合把 20 步压到 8 步且画质稳定的常规文生图/图生图负载；不适合把“少步”当作万能药去覆盖超高分辨率与强文本约束——这两类场景受直线假设限制，需要更多步或叠加蒸馏补偿。它与一致性模型的区别也要讲清：一致性模型靠蒸馏把多步压成一步，依赖教师模型；整流流是训练期重参数化路径，不依赖教师，二者可叠加进一步压步数。工程判断落在监控上：把“多物体提示词的成图结构一致性”和“文字区域的笔画可读性”做成少步配置的准入指标，一旦回退率抬头，优先加步数或换中点法，而不是先动量化和批调度。</p>\n<h3 id=\"alg-rectified-flow-sampler-sec-7\">七 · 从请求到第一个 latent：入口与时间网格</h3>\n<p>一个整流流采样请求进入服务栈后，最先被确定下来的不是模型权重，而是两样东西：批的形状与离散时间网格。请求形态是文生图或图生图的单次 latent 生成，批大小按显存与 SLO 在 1–8 之间取；时间网格则是把连续区间 $t\\in[0,1]$ 切成 $N$ 段，得到 $t_0=1,t_1,\\dots,t_N=0$ 与步长 $\\Delta t_k=t_{k+1}-t_k$。注意方向：整流流推理从纯噪声 $x_1=\\varepsilon$ 出发向 $x_0$ 走，所以 $t$ 递减、$\\Delta t$ 取负。这一步的输入是提示词、可选参考图、批大小与步数；输出是一块形状为 $[B,C,H,W]$ 的噪声 latent、一份 timestep embedding 表，以及一个被 scheduler 消费的步长序列。</p>\n<p>代价集中在显存与带宽而非算力：latent 本身按 $B\\times C\\times H\\times W$ 线性增长，timestep embedding 按批与分辨率线性增长，二者合起来就是这套算法语境下的“KV”——它不像自回归解码那样随序列长度爆炸，但对高分辨率与大批量同样敏感。以 8 步、批 4 的配置为例，入口阶段几乎没有 GEMM，耗时被 host 侧的调度与 kernel launch 主导，因此在 Blackwell 上应把时间网格与 embedding 预计算放进一次融合 kernel，避免每步重复搬运。时间网格的选择直接决定后面所有步骤的误差结构：Euler 只用 $t_k$ 处的速度，中点法要在 $t_k$ 与半步点各取一次，网格必须同时容纳两者。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-8\">八 · 单步速度场前向：DiT 主体与条件注入</h3>\n<p>每一步的核心是 $v_\\theta(x_k,t_k)$ 的一次前向。输入是当前 latent、当前时间标量（经 embedding 注入每个 DiT block 的调制支路）以及条件上下文；输出是与 latent 同形状的速度张量。条件注入有两条路径：CFG 打开时把条件与非条件拼成一个 batch 走同一次前向，即 CFG 批合并，把两次前向摊成一次更大的 GEMM；条件缓存则把不随步变化的交叉注意力 K/V 留在片上或显存里复用。这两者的细节属于相邻条目，此处只作为本步骤的输入约定。</p>\n<p>这一步是整条链路唯一的重算力环节，代价可以用一个粗粒度的量纲刻画：单步 FLOPs 约与 $B\\cdot P\\cdot d^2$ 成正比（$P$ 为 patch/token 数，$d$ 为隐维），而实际耗时取决于能否把 GEMM 喂满。Blackwell 上的做法是把主体 GEMM 落到 FP8 或 NVFP4，让 tcgen05 的 MMA 与 TMEM 承担累加，注意力走异步 FA 变体；量化误差在少步下会被放大，因为每一步的残差都直接进入下一时刻的 latent，没有多步平均来稀释。工程判断是：步数越少，越应该把量化精度留给末端几步，前端大步长阶段对速度场的绝对误差不敏感、对方向误差敏感。</p>\n<div class=\"formula\">$$v_\\theta(x_k,t_k)=\\text{DiT}\\big(x_k,\\ \\text{emb}(t_k),\\ c\\big),\\qquad \\text{cost}\\propto B\\cdot P\\cdot d^2$$</div>\n<p>具体例子：批 4、8 步、CFG 批合并后等效批 8 的配置下，单步前向是整条流水线的吞吐瓶颈；若把这一步的 GEMM 从 BF16 换成 FP8，单步时延下降，但末端两步若同样量化，VAE 解码容易出现色块——这正是失败模式里“末端 latent 分布偏移”的来源之一。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-9\">九 · Euler 更新：一步一前向的代价结构</h3>\n<p>拿到速度场后，更新是纯逐元素操作：$x_{k+1}=x_k+\\Delta t\\,v_\\theta(x_k,t_k)$。输入是当前 latent、速度张量与步长；输出是下一时刻 latent。它没有矩阵乘、没有归约，带宽受限而非算力受限：读写各一遍 latent，外加一次标量乘加。放在 Blackwell 上，这个 kernel 应该和上一步的 epilogue 融合，让速度张量留在片上直接完成累加，避免一次完整的 HBM 往返——对 $[4,16,128,128]$ 的 latent，一次往返就是数 MB 级别的流量，8 步累计下来足以和若干次小 GEMM 的耗时相比。</p>\n<p>Euler 的代价结构非常干净：每步一次前向、一次逐元素更新，单步成本就是一次 DiT 前向加一次带宽操作。它的误差是 $O(\\Delta t)$ 量级的一阶局部截断，但因为速度沿直线恒定，累积误差随步长线性而非高阶累积，这正是 20 步压到 8 步仍能维持画质的机制来源。工程上的取舍是：步长越大，单图时延越低，但末端 latent 的分布偏移越明显；8 步是常见配置，4 步则要靠蒸馏或更细的末端网格补偿。</p>\n<p>具体例子：单卡 B200 上跑批 1 的 8 步 Euler，前向占绝大部分时间，更新 kernel 的耗时占比很小但仍不可忽略——若不做融合，每步多出一次全量 latent 读写，8 步的额外带宽开销会直接体现在单图时延上。这也是为什么“Euler 大步长配置”在单图场景下往往比“中点法小步长”更划算。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-10\">十 · 二阶中点法：两次前向换精度</h3>\n<p>中点法把一步拆成两半：先用 $t_k$ 处的速度走半步到预测点，再在预测点取速度做校正。伪代码思路是：</p>\n<ul>\n<li>输入 $x_k,t_k,\\Delta t$；</li>\n<li>取 $v_1=v_\\theta(x_k,t_k)$，构造 $x_{mid}=x_k+\\tfrac{\\Delta t}{2}v_1$；</li>\n<li>取 $v_2=v_\\theta(x_{mid},t_k+\\tfrac{\\Delta t}{2})$；</li>\n<li>输出 $x_{k+1}=x_k+\\Delta t\\,v_2$。</li>\n</ul>\n<p>代价立刻翻倍：单步两次 DiT 前向，算力与显存带宽占用都乘以二，而精度收益是局部截断从一阶升到二阶。这在直线轨迹上收益有限——速度恒定意味着 $v_1\\approx v_2$，中点法的校正量很小；但在直线假设不严格成立的区域（多物体、文字渲染），二阶项恰好捕捉轨迹的轻微弯曲，能减少结构错位。工程判断因此是分段的：前端大步长用 Euler 省算力，末端一两步换中点法补精度，总前向次数介于纯 Euler 与全程中点之间。</p>\n<div class=\"formula\">$$x_{k+1}=x_k+\\Delta t\\,v_\\theta\\!\\Big(x_k+\\tfrac{\\Delta t}{2}v_\\theta(x_k,t_k),\\ t_k+\\tfrac{\\Delta t}{2}\\Big)$$</div>\n<p>具体例子：批 1、8 步、全程中点法的配置下前向次数为 16，若不加 CFG 批合并，单图时延反而高于 Euler 大步长配置——这正是失败模式里点名的情形。把中点法限制在末端两步，前向次数降到 10，既保住末端细节又没让时延翻倍。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-11\">十一 · 末端 latent 交付与 VAE 解码的衔接</h3>\n<p>第 $N$ 步输出 $x_0$ 后，latent 被送进 VAE 解码。输入是最终 latent 与解码器的权重；输出是像素图。这一步的代价与采样阶段性质不同：解码器本身是一次前向，但分辨率越高、分块越多，显存峰值与带宽压力越突出，VAE 分块并行解码是相邻条目的主题，此处只强调衔接处的两个约束。其一是数值一致性：采样阶段若在末端用了 FP8/NVFP4，latent 的分布已经偏移，解码器对输入的尺度敏感，容易出现色块或结构崩坏；其二是步长与末端网格：$\\Delta t$ 过大时最后一步的残差最大，$x_0$ 落在分布外，解码器无法把它映射回自然图像。</p>\n<p>因此末端一步的工程处理是：缩小 $\\Delta t$、必要时切回更高精度、并在 CFG 系数上按步数重调——少步下引导系数过大会导致过饱和，颜色先崩，结构后崩。这条链路上的显存代价也要算清楚：采样阶段的 latent 与 timestep embedding 缓存尚未释放时若直接进解码，峰值显存是两者之和；批 4 以上时应在交付前把采样侧的中间缓冲归还，否则解码分块会被挤到更小的块尺寸，反而拖慢吞吐。</p>\n<p>具体例子：8 步配置下若末端两步仍用 FP8 且 CFG 系数沿用 20 步时的取值，解码输出常见过饱和与色偏；把末端两步切回 BF16 并把引导系数下调，画质恢复而总时延只增加末端两步的开销——这是少步部署里性价比最高的一处调整。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-12\">十二 · 步骤顺序里的调度与复用判断</h3>\n<p>把上述步骤按 token/KV 流动的顺序排开，可以看到一条清晰的代价分布：入口阶段是 host 侧调度与 embedding 预计算，中间 $N$ 步是重算力前向加带宽型更新，末端是精度敏感的解码衔接。调度器要利用的正是这个分布——不同请求的步数可以不同，把末端步的请求与前端步的请求混批会拉长关键路径；把步数相同、分辨率相同的请求聚成一批，则能让 CFG 批合并后的 GEMM 形状稳定，减少 kernel 重编译与尾效应。连续批处理在这里的形态与自回归解码不同：它不是按 token 逐步插入，而是按“步”这个粒度做批的进出，一个请求跑完 8 步才释放槽位，所以批的驻留时间由步数决定。</p>\n<p>复用的判断落在两处。时间网格与 timestep embedding 可以跨请求复用，因为整流流的速度场参数化统一、scheduler 不绑定模型，这是它相对 DDIM 的工程优势；条件侧的交叉注意力 K/V 缓存则只在同提示词的连续请求间有效。代价是缓存占用随批与分辨率线性增长，在显存紧张时优先牺牲条件缓存而不是时间网格。最终落在具体机制上：把 8 步的网格、末端两步的精度切换、CFG 系数的按步重调写进同一条调度策略里，比单独优化任何一步都更能决定单图时延与画质的平衡点。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-13\">十三 · 边界条件：直线假设失效与二阶积分的真实开销</h3>\n<p>整流流把采样代价从“步数×单步前向”改写为“步长误差可控下的最少前向次数”，但这条等式只在直线假设成立时闭合。失效点首先出现在条件复杂度上：多物体布局、文字渲染、细粒度属性绑定这类任务，其真实概率路径在条件子空间里仍带弯曲，直线插值给出的恒定速度场只是对弯曲路径的一阶近似。少步离散化时，误差不再随步长线性收敛，而是以结构错位的形式暴露——物体数量对、位置错，或文字笔画粘连。此时系统的补救手段只有两种：回退到更多步（把 8 步配置拉回 20 步量级），或叠加少步蒸馏用教师信号补偿直线假设的残差。前者直接抬高单图时延，后者引入额外训练资产与部署复杂度，二者都不是免费的。</p>\n<p>第二个边界是积分器阶数与单步成本的权衡。Euler 更新 $x_{k+1}=x_k+\\Delta t\\,v_\\theta(x_k,t_k)$ 每步一次前向，中点法先取半步预测再校正，单步需两次前向。设单次 DiT 前向在给定分辨率与批下的时延为 $\\tau$，则 $N$ 步 Euler 的采样时延约为 $N\\tau$，中点法约为 $2N\\tau$；若中点法能把所需步数从 $N$ 压到 $N/2$ 以下，才在时延上打平。工程上更常见的是保持 Euler 大步长、把省下的算力投给 CFG 批合并——把条件与非条件前向拼成一个 batch，使有效前向次数减半而非翻倍。单图、批大小为 1 的部署里，中点法若不做批合并，时延反而高于 Euler 大步长配置，这是选型时最容易被忽略的一笔账。</p>\n<p>第三个边界落在末端 latent 的分布偏移上。步长过大时，$x_k$ 序列并未真正贴近直线，末端 latent 的统计特性偏离 VAE 解码器训练时见到的分布，解码端表现为色块、结构崩坏或高频细节糊化。CFG 引导系数在少步下被放大，会进一步把样本推向过饱和区域，色彩崩坏与过饱和同时出现。可操作的判断是：把引导强度与步数绑定重调，而非沿用 20 步配置的系数；把分辨率与步数绑定评估，超高分辨率与强文本约束场景默认不走 4–8 步档，除非蒸馏补偿已就位。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统代价落点</th><th>工程处置</th></tr></thead><tbody><tr><td>多物体/文字条件</td><td>画质崩塌，需回退步数，单图时延上升</td><td>提高步数档或叠加少步蒸馏</td></tr><tr><td>中点法未批合并</td><td>单步前向翻倍，单图时延高于 Euler</td><td>CFG 批合并后再评估阶数</td></tr><tr><td>步长过大+CFG 过强</td><td>末端 latent 偏移，VAE 解码崩坏</td><td>按步数重调引导系数，限分辨率档</td></tr></tbody></table>\n<p>把这些边界折进容量规划，单图 SLO 为 8 步内出图时，可用的余量实际取决于批大小与是否批合并：批大小在 1–8 间取值摊薄前向开销，latent 与 timestep embedding 缓存随批与分辨率线性增长，显存占用在 FP8/NVFP4 主体 GEMM 下才留得住 8 步配置的中间激活。直线假设带来的收益是调度器可跨模型复用、实现简单，但它的代价集中在条件复杂度与积分器选择这两处——部署时若不把这两项写进 SLO 验收项，少步配置会在真实请求分布上以画质回退的形式还账。</p>\n<h3 id=\"alg-rectified-flow-sampler-sec-14\">十四 · 直线插值的逐项解剖：为什么 t 的系数决定误差阶</h3>\n<p>核心公式的第一项是 $x_t=(1-t)x_0+t\\varepsilon$。它不是把噪声“加”到样本上，而是把样本与噪声放在同一条线段的两端，用 $t$ 做凸组合。$t=0$ 时 $x_t=x_0$（数据端），$t=1$ 时 $x_t=\\varepsilon$（噪声端）。逐项看：$(1-t)$ 是数据权重，随 $t$ 线性衰减；$t$ 是噪声权重，线性上升；两者之和恒为 1，所以 $x_t$ 始终落在 $x_0$ 与 $\\varepsilon$ 的连线上，不产生任何法向偏移。这一点是整条推导的支点——DDPM 的前向过程写成 $x_t=\\sqrt{\\bar\\alpha_t}x_0+\\sqrt{1-\\bar\\alpha_t}\\varepsilon$，两个系数是 $\\bar\\alpha_t$ 的函数，其比值随 $t$ 非线性变化，轨迹在 $x_0$–$\\varepsilon$ 平面上是一条弯的曲线；而整流流的系数比 $(1-t)/t$ 单调且线性，轨迹退化为直线。</p>\n<p>关键的一步在这里：对 $x_t$ 求全导数，</p>\n<div class=\"formula\">$$\\frac{dx_t}{dt}=\\frac{d}{dt}\\big[(1-t)x_0+t\\varepsilon\\big]=\\varepsilon-x_0$$</div>\n<p>导数与 $t$ 无关，是一个常数向量。这意味着如果网络精确学到了 $v_\\theta(x_t,t)=\\varepsilon-x_0$，那么沿整条路径的速度场处处相同，ODE 的解就是直线本身。于是积分不再需要“跟随弯曲流形”，而只是沿一个常向量做线性外推。误差分析随之简化：Euler 法单步局部截断误差正比于 $\\Delta t^2\\cdot|v'|$，而 $v'=0$，所以局部误差只剩高阶项；全局误差随 $\\Delta t$ 线性增长而非在弯曲轨迹上被曲率放大。这就是“大步长可用”的数学来源，也是 20 步压到 8 步仍能维持画质的根据。代价面：直线假设要求 $v$ 在整条线段上恒定，一旦条件（多物体、文字）使真实边际路径偏离直线，$v'$ 不再为零，误差重新抬头，少步下细节先丢。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-15\">十五 · 损失函数的期望结构与梯度含义</h3>\n<p>监督目标是 $\\mathcal{L}=\\mathbb{E}\\|v_\\theta(x_t,t)-(\\varepsilon-x_0)\\|^2$。逐项拆：期望对 $x_0\\sim p_{\\text{data}}$、$\\varepsilon\\sim\\mathcal{N}(0,I)$、$t\\sim U[0,1]$ 三重采样；$x_t$ 由前两项与 $t$ 确定，不是独立变量；回归目标是 $\\varepsilon-x_0$，方向从数据指向噪声，模长等于两者距离。这个损失与 DDPM 的噪声预测损失形式相似，但语义不同：DDPM 回归的是 $\\varepsilon$，其最优解依赖 $\\bar\\alpha_t$ 的调度；整流流回归的是端点差，最优解 $v^*(x_t,t)=\\mathbb{E}[\\varepsilon-x_0\\mid x_t]$ 只依赖 $x_t$ 处的条件期望，与任何 scheduler 无关。这正是“scheduler 可跨模型复用”的根源——推理端只需要一组离散时间点 $t_k$，不需要与训练时的噪声调度表对齐。</p>\n<p>梯度层面，$\\nabla_\\theta\\mathcal{L}=2\\mathbb{E}[(v_\\theta-v^*)\\cdot\\nabla_\\theta v_\\theta]$，误差按 $x_t$ 上的条件期望加权。工程含义：$t$ 均匀采样使每个时间片获得同等梯度预算，靠近 $t=0$（数据端）与 $t=1$（噪声端）的区间都被充分训练，而 DDPM 常用余弦或线性 $\\bar\\alpha$ 调度会让某些区间样本稀疏。系统代价上，这意味着训练侧不需要为 scheduler 调参留接口，推理侧可以把 $t_k$ 的选取完全交给部署方；但代价是模型对 $t$ 的连续性要求更高——离散 $t_k$ 若取得过疏，$v_\\theta$ 在相邻点之间的插值误差无法被损失约束，于是少步配置下末端 latent 分布偏移，VAE 解码出色块。例子：8 步配置取 $t_k=k/8$，若模型在 $t=0.875$ 附近欠拟合，最后一步外推会把 latent 推出训练分布，表现为结构崩坏。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-16\">十六 · Euler 与中点法的可实现伪代码</h3>\n<p>推理循环的可实现形态如下（伪代码思路，非 <code>pre</code> 块）：输入噪声 $x_1$、时间网格 $\\{t_k\\}_{k=0}^{N}$ 满足 $t_0=1,t_N=0$、步长 $\\Delta t_k=t_{k+1}-t_k$（负值）。对每个 $k$：取 $v_1=v_\\theta(x_k,t_k)$；Euler 直接令 $x_{k+1}=x_k+\\Delta t_k\\cdot v_1$。中点法则先取半步 $x_{mid}=x_k+\\frac{\\Delta t_k}{2}v_1$，再算 $v_2=v_\\theta(x_{mid},t_k+\\frac{\\Delta t_k}{2})$，最后 $x_{k+1}=x_k+\\Delta t_k\\cdot v_2$。注意时间参数要同步推进到半步点，否则中点法退化为错误的二阶格式。循环结束后 $x_N$ 即末端 latent，送 VAE 解码。</p>\n<p>逐项代价：Euler 每步一次 DiT 前向，8 步即 8 次；中点法每步两次前向，8 步即 16 次，单图时延在无批合并时接近翻倍。若把 CFG 的条件与非条件前向拼成一个 batch，则每次前向的实际开销被摊薄，中点法的边际成本从“两次前向”降为“一次 batch 扩倍的前向”，这是部署配方里 CFG 批合并与二阶积分必须一起考虑的原因。显存面：latent 缓存按 batch×分辨率线性增长，中点法额外保留 $x_{mid}$ 与 $v_1$，增量约为单个 latent 张量；在 B200/GB200 上这部分增量相对 DiT 主体权重可忽略，但在高分辨率、大 batch 下会挤压并发槽位。带宽面：每步前向要读一遍权重、写一遍激活，中点法把权重读取次数翻倍，权重带宽成为少步二阶配置的隐性瓶颈——若权重已用 FP8/NVFP4 压缩，读取压力下降，中点法的可行性随之提高。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-17\">十七 · 时间网格与步长的工程取舍</h3>\n<p>离散时间点 $t_k$ 的选取不是均匀就好。直线轨迹上误差对 $\\Delta t$ 线性，但 $v_\\theta$ 在 $t$ 接近 1（纯噪声端）时方差大、在 $t$ 接近 0 时接近数据流形，条件期望的曲率不同。常见做法是在两端加密、中段放稀，或用非均匀网格让末端步长更小以压低 VAE 解码前的分布偏移。公式上，若采用非均匀 $\\Delta t_k$，Euler 更新仍是 $x_{k+1}=x_k+\\Delta t_k v_\\theta(x_k,t_k)$，但误差界变为 $\\sum_k|\\Delta t_k|^2|v'|$ 的累积，网格设计直接决定少步下的画质下限。</p>\n<p>例子：8 步配置若均匀取 $t_k=1-k/8$，末端步长为 $1/8$；若改为末端两步各取 $1/16$、前段合并，则末端外推距离减半，色块概率下降，但前段步长变大可能丢中频细节。系统代价：网格是纯推理侧参数，不触发重训，可在服务端按请求类型（文生图 vs 图生图）切换；代价是网格与模型绑定度上升，跨模型复用 scheduler 的卖点被削弱——复用的是“速度场参数化”，不是“网格本身”。这也是为什么整流流宣称 scheduler 可复用时要限定在参数化层面：$t_k$ 仍需按模型的实际 $v_\\theta$ 平滑度重调。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-18\">十八 · 与 CFG、少步蒸馏叠加时的公式变形</h3>\n<p>CFG 在整流流里的形式是 $v_{cfg}=v_\\theta(x_t,t,c)+\\omega\\,(v_\\theta(x_t,t,c)-v_\\theta(x_t,t,\\varnothing))$，其中 $\\omega$ 为引导系数。逐项看：条件速度与非条件速度之差被放大 $\\omega$ 倍，等价于把速度场往条件方向推。直线假设下，这个推挤仍是常向量叠加，不破坏直线性；但 $\\omega$ 过大时，$v_{cfg}$ 的模长超出训练分布，末端 latent 被推出流形，少步下表现为过饱和与色彩崩坏。工程判断：$\\omega$ 需按步数重调，步数越少、$\\omega$ 越应保守，因为大步长把单步的推挤量放大。</p>\n<p>少步蒸馏叠加时，学生模型不再回归 $\\varepsilon-x_0$，而是直接回归“从 $x_{t_k}$ 到 $x_{t_{k+1}}$ 的位移”，损失变为 $\\|f_\\theta(x_{t_k},t_k)-(x_{t_{k+1}}-x_{t_k})\\|^2$。这等价于把 Euler 更新吸收进网络，推理时一次前向跨多步。代价：蒸馏需要教师轨迹，教师本身用整流流采样，蒸馏误差与直线假设误差叠加；收益是步数可压到 4 步甚至更少。系统面：蒸馏后每步前向次数下降，但模型输出维度不变，显存与带宽不降，收益全在时延侧；若 SLO 要求单图 8 步内出图，蒸馏是把 8 步压到 4 步、把时延减半的直接手段，代价是画质在复杂条件下的下限更低，需保留回退到 8 步 Euler 的路径。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-19\">十九 · 失败模式的公式定位与回退策略</h3>\n<p>三类失败都能在公式里找到位置。其一，多物体与文字场景：真实边际路径不是直线，$v'$ 非零，Euler 全局误差随 $\\Delta t$ 线性累积，少步下细节先丢——定位在“直线假设”这一项，回退是加步或叠蒸馏。其二，中点法单图时延反超 Euler：定位在“每步两次前向”这一项，若无 CFG 批合并摊薄，二阶格式的常数因子压过误差收益；工程判断是先做批合并再上中点法，否则大步长 Euler 更划算。其三，CFG 过饱和：定位在 $\\omega$ 放大项，少步下推挤量被大步长放大，回退是按步数下调 $\\omega$ 或改用条件缓存减少非条件前向的重复计算。</p>\n<p>回退策略的可实现形态：服务端维护两套配置——8 步 Euler（默认，单次前向、时延低）与 4 步蒸馏（快速路径），按请求的文本复杂度或分辨率触发切换；末端 latent 分布偏移的检测可放在 VAE 解码前，用 latent 的范数或分块统计量做轻量判据，异常则回退到更多步重采。代价：双配置意味着权重或 LoRA 增量常驻，显存占用上升；判据本身引入额外读带宽。在 Blackwell 上，这部分开销相对 DiT 主体较小，但高并发下判据的同步点会成为流水线气泡，需与连续批处理调度一起设计，避免判据阻塞整个 batch 的推进。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-20\">二十 · 直线假设的裂缝：失效条件、二阶代价与可落地的伪代码</h3>\n\n<p>整流流的推导起点是监督目标 <span class=\"formula-inline\">$$\\mathcal{L}=\\mathbb{E}\\|v_\\theta(x_t,t)-(\\varepsilon-x_0)\\|^2$$</span> 在直线插值下取到零，于是速度场沿路径恒定，Euler 更新 <span class=\"formula-inline\">$$x_{k+1}=x_k+\\Delta t\\,v_\\theta(x_k,t_k)$$</span> 的局部截断误差只与 <span class=\"formula-inline\">$$\\Delta t$$</span> 的二次方成正比，而非 DDIM 弯曲路径上的高阶累积——这是“20 步压到 8 步”的数学来源，也是它全部边界条件的来源。关键一步在于：恒定速度意味着 <span class=\"formula-inline\">$$\\partial v/\\partial t=0$$</span>，但网络实际输出的是条件期望 <span class=\"formula-inline\">$$v_\\theta(x_t,t)=\\mathbb{E}[\\varepsilon-x_0\\mid x_t]$$</span>，当同一 <span class=\"formula-inline\">$$x_t$$</span> 对应多条互不相容的直线（多物体、文字笔画、强文本约束）时，条件期望把若干方向平均掉，速度场不再恒定，直线假设在采样轨迹上失效。此时误差不再随 <span class=\"formula-inline\">$$\\Delta t$$</span> 线性收敛，少步直接表现为结构错位与细节丢失，而不是单纯的模糊。</p>\n\n<p>二阶中点法把这一步的代价摊开：半步预测 <span class=\"formula-inline\">$$x_{k+1/2}=x_k+\\tfrac{\\Delta t}{2}v_\\theta(x_k,t_k)$$</span>，再校正 <span class=\"formula-inline\">$$x_{k+1}=x_k+\\Delta t\\,v_\\theta(x_{k+1/2},t_{k+1/2})$$</span>，单步两次前向。设单次 DiT 前向在 B200 上的时延为 <span class=\"formula-inline\">$$\\tau$$</span>，Euler 的 8 步总时延为 <span class=\"formula-inline\">$$8\\tau$$</span>，中点法 8 步为 <span class=\"formula-inline\">$$16\\tau$$</span>；若中点法能把步数压到 5 步，则是 <span class=\"formula-inline\">$$10\\tau$$</span>，仍高于 Euler 大步长配置。批大小为 1 时这部分开销无法摊薄，单图时延反而更差；只有把 CFG 的条件与非条件前向合并成一个 batch，或把 batch 拉到 4–8，让两次前向共享同一批权重加载与 TMEM 占用，中点法才有吞吐上的意义。这是选型时必须先算的一笔账，而不是默认“二阶更准就更好”。</p>\n\n<p>伪代码落到可实现层面，边界判断要写进循环而不是事后补救。时间网格取 <span class=\"formula-inline\">$$t_k=k/K,\\ k=0..K$$</span> 时注意方向约定：训练用 <span class=\"formula-inline\">$$x_t=(1-t)x_0+t\\varepsilon$$</span>，<span class=\"formula-inline\">$$t=1$$</span> 为纯噪声，推理须从 <span class=\"formula-inline\">$$t=1$$</span> 向 <span class=\"formula-inline\">$$t=0$$</span> 反向积分，即 <span class=\"formula-inline\">$$\\Delta t=-1/K$$</span>，符号写错会直接得到噪声残影。末端一步不要走满 <span class=\"formula-inline\">$$\\Delta t$$</span>：最后一段速度场在 <span class=\"formula-inline\">$$t\\to 0$$</span> 附近对 <span class=\"formula-inline\">$$x_0$$</span> 的估计最敏感，步长过大时末端 latent 分布偏移，VAE 解码出现色块或结构崩坏，工程上常把末步缩到 <span class=\"formula-inline\">$$\\Delta t/2$$</span> 并单独校一次速度场。CFG 系数须按步数重调：少步下引导过强会过饱和，把 <span class=\"formula-inline\">$$w$$</span> 从 20 步配置的取值下调，否则色彩先崩。</p>\n\n<table class=\"mini\">\n<thead><tr><th>配置</th><th>前向次数</th><th>相对时延</th><th>适用边界</th></tr></thead>\n<tbody>\n<tr><td>Euler，8 步，batch 1</td><td>8</td><td>基准</td><td>简单构图、快速出图</td></tr>\n<tr><td>Euler，8 步 + CFG 批合并</td><td>8（合并后）</td><td>低于基准</td><td>常规文生图</td></tr>\n<tr><td>中点法，5 步，batch 1</td><td>10</td><td>高于基准</td><td>不推荐</td></tr>\n<tr><td>中点法，5 步，batch 4–8</td><td>10</td><td>摊薄后可接受</td><td>多物体、文字场景</td></tr>\n<tr><td>回退 12–20 步或叠加蒸馏</td><td>≥12</td><td>显著上升</td><td>超高分辨率、强文本约束</td></tr>\n</tbody>\n</table>\n\n<p>系统代价还落在显存与缓存一侧：latent 与 timestep embedding 缓存随 batch 与分辨率线性增长，中点法的半步中间量 <span class=\"formula-inline\">$$x_{k+1/2}$$</span> 必须保留到校正前向，等于多占一份同尺寸 latent；在 FP8/NVFP4 主体 GEMM 下这部分显存不参与计算却挤占 batch 上限，直接把可选 batch 从 8 压到 4，反过来又削弱了摊薄效果。因此判断顺序应是：先确认场景是否落在直线假设成立的一侧（单主体、弱文本约束），成立则 Euler 大步长加 CFG 批合并是首选；不成立则先试少步蒸馏把步数压到 4 以下，再考虑中点法，且必须配 batch≥4 与末步缩短，否则单图时延与画质两头不讨好。</p>\n<h3 id=\"alg-rectified-flow-sampler-sec-21\">二十一 · 请求形态：单次 latent 生成才是它的主场</h3>\n<p>整流流直线采样器的负载画像首先由请求形态决定。它服务的是文生图、图生图的<strong>单次 latent 生成</strong>：一个 prompt（或一张参考图加 prompt）对应一次从纯噪声 $x_1$ 到 latent $x_0$ 的积分，末端 latent 交给 VAE 解码成像素。这个形态意味着请求之间几乎没有共享前缀——不像自回归解码可以靠前缀缓存摊薄预填，也不像视频生成可以在时间维上复用帧间状态。每个请求都是一条独立的、从 $t=1$ 走到 $t=0$ 的短轨迹，轨迹内部有严格的顺序依赖：$x_{k+1}$ 必须等 $v_\\theta(x_k,t_k)$ 算完。</p>\n<p>这条依赖链决定了它的并发模型是<strong>批内并行、步间串行</strong>。同一个 batch 里的 N 个样本在第 k 步可以拼成一次大 GEMM 一起前向，但第 k+1 步必须等第 k 步全部返回。于是批大小成为把单步 GEMM 从“瘦”变“胖”的唯一杠杆：批太小，DiT 主体的矩阵乘在 Blackwell 的 tcgen05 上利用率不足，权重读取的显存带宽开销摊不薄；批太大，单步时延上升、尾请求等待变长，SLO 被击穿。这就是为什么负载配方把批大小锁在 1–8 这个窄区间——它不是拍脑袋，而是单步前向的算力/带宽比与单图时延约束共同挤压出来的窗口。</p>\n<p>与之配套的是 CFG 批合并：把条件前向与非条件前向拼进同一个 batch，一次前向出两份速度场再线性组合。若不合并，CFG 等于把每步前向次数翻倍，单图时延直接乘二；合并后两份计算共享同一批权重加载，代价从“两次前向的时延”降为“一次两倍宽前向的时延”。这是负载配方里少数几个不牺牲画质就能拿到的收益。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-22\">二十二 · 长度分布：步数是唯一的“序列长度”</h3>\n<p>扩散采样没有 token 长度分布，它的“长度”就是<strong>积分步数 K</strong>。整流流把常见配置从 20 步压到 8 步，SLO 通常要求单图 8 步内出图，4–8 步是它的目标工作点。这个数字不是随意选的：直线轨迹让积分误差随步长线性累积而非高阶累积，所以 8 步的离散化误差仍在画质可接受范围内；再往下压到 4 步，误差开始在多物体与文字场景显形。</p>\n<p>步数对系统代价的影响是<strong>线性乘性</strong>的。设单步前向时延为 $\\tau$，Euler 采样的单图时延近似为</p>\n<div class=\"formula\">$$T_{\\text{Euler}} \\approx K\\cdot\\tau + T_{\\text{VAE}},\\qquad T_{\\text{midpoint}} \\approx 2K\\cdot\\tau + T_{\\text{VAE}}$$</div>\n<p>二阶中点法每步两次前向（先取半步预测再校正），单步成本翻倍，换来的是同样步数下更小的离散化误差。于是出现一个反直觉的工程判断：在批大小=1、无批合并的场景下，中点法大步长配置的单图时延可能<strong>高于</strong>Euler 大步长配置——多出来的那次前向没有别的请求来摊薄。负载配方因此必须把“步数 × 每步前向次数”当作一个整体来配：要么 Euler 8 步，要么中点法 4 步，而不是中点法 8 步硬扛。</p>\n<p>长度分布的另一个维度是<strong>分辨率</strong>。latent 的空间尺寸随出图分辨率线性增长，单步前向的 FLOPs 与激活显存随之上升，KV（这里指 latent 与 timestep embedding 缓存）按 batch 与分辨率线性增长。高分辨率请求等于把每个“步”变贵，于是同样的 8 步预算下，高分辨率请求的批大小必须下调，否则单步时延与显存同时越界。负载配方里批大小与分辨率是一对联动参数，不能独立设定。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-23\">二十三 · 并发与批大小：批内并行、步间串行的调度约束</h3>\n<p>连续批处理那套“请求随时进出、按 token 步进”的机制在这里不适用，因为一个请求的 8 步是一条不可分割的链，中途插入新请求只会让它在 batch 里空等。可行的调度是<strong>批次级准入</strong>：攒够一批请求（或等到超时）后整批走完 K 步再释放，期间不接纳新请求。这带来一个队列层面的代价——批形成期的等待时间直接加到端到端时延上，批越大等待越久。负载配方要在“批大摊薄单步成本”与“批大拉长排队时延”之间取平衡点，1–8 的窗口正是这个平衡的产物。</p>\n<p>伪代码层面的准入逻辑大致是：</p>\n<ul>\n<li>维护一个待采样队列，按分辨率与步数配置分桶，避免同一 batch 内混入不同 latent 尺寸导致 padding 浪费；</li>\n<li>当桶内请求数达到目标批大小，或队首等待超过阈值，锁定该批并一次性分配 latent 缓存；</li>\n<li>整批执行 K 步前向，每步内部把条件/非条件拼成 CFG 合并 batch；</li>\n<li>批完成后统一送 VAE 解码并释放缓存，再解锁下一批。</li>\n</ul>\n<p>这里的关键代价是<strong>显存驻留时间</strong>：一批请求的 latent 在整个 K 步期间常驻，批越大、分辨率越高、步数越多，驻留显存越多。Blackwell 单卡显存有限，批大小实际上被“K 步 × batch × latent 尺寸”这个乘积卡住，而不是被算力卡住。这也是为什么负载配方把批大小上限压在 8：再往上，显存先于算力成为瓶颈。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-24\">二十四 · 负载不对时：三种可观测的崩坏</h3>\n<p>负载配方错配不会安静地退化，它会以三种方式显形。第一种是<strong>批太小导致带宽饥饿</strong>：批大小=1 时，DiT 主体的权重加载带宽开销无法摊薄，单步前向的算力利用率低，吞吐上不去而时延并不因此变好——你付了全部权重读取的代价却只算了一个样本。这在 Blackwell 上尤其明显，因为 tcgen05 的 MMA 吞吐很高，喂不饱时浪费的是整个 tensor core 阵列的周期。</p>\n<p>第二种是<strong>步数压过头导致画质崩坏</strong>：直线假设在多物体、文字渲染等复杂条件下不严格成立，少步会丢细节、结构错位。更隐蔽的是 CFG 引导系数在少步下过大引起过饱和与色彩崩坏——引导强度是按步数调的，把 20 步的系数直接搬到 8 步配置上，末端 latent 分布偏移，VAE 解码出现色块。负载配方必须把 CFG 系数与步数绑定成一组参数，而不是各自独立配置。</p>\n<p>第三种是<strong>步长过大导致末端 latent 分布偏移</strong>：当 $\\Delta t$ 大到速度场在一步内变化显著时，Euler 更新把 latent 推出训练分布覆盖的区域，VAE 解码出现结构崩坏。这是直线假设失效的直接后果，也是“4 步是下限、8 步是常规”这条经验线的物理来源。回退手段只有两个：加步数，或叠加少步蒸馏用教师信号补偿直线假设的残差。</p>\n<p>三种崩坏的共同点是它们都不体现在单步前向的 profiler 里，而体现在端到端指标上：吞吐、P99 时延、以及需要人工抽检的画质。负载配方因此不能只看算力利用率，必须把画质回归纳入容量规划的闭环。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-25\">二十五 · 配方边界：什么时候该换算法而不是调参</h3>\n<p>负载配方有它的适用边界。它适合 4–8 步快速出图与跨模型复用 scheduler 的场景：速度场形式统一，scheduler 不绑定具体模型，工程实现简单，换模型不用重调采样器。但当负载落在边界之外——超高分辨率、强文本约束、多物体复杂构图——直线假设的残差变大，配方里的“8 步”不再够用，此时正确的动作不是把批大小或 CFG 系数拧来拧去，而是换手段：加步数回到 20 步档，或叠加少步蒸馏把多步压成更少步。</p>\n<p>与一致性模型的对比在这里给出一个工程判断的分水岭：一致性模型靠蒸馏把多步压成一步，依赖教师模型，蒸馏成本前置；整流流是训练期重参数化路径，不依赖教师，可与少步蒸馏叠加进一步压步数。所以负载配方的选择逻辑是——如果请求形态稳定、分辨率与文本复杂度可控，整流流 8 步配方是默认档；如果请求形态里高复杂度占比高且 SLO 极紧，则在整流流之上叠蒸馏，而不是单纯把步数往下砍。</p>\n<p>规模上限同样由直线假设划定：论文 paper-rectified-flow-a-marginal-preserving-2022 与 paper-scaling-rectified-flow-transformers-2024 给出机制与扩展证据，但具体吞吐数字未给出，容量规划只能定性判断——分辨率与文本约束越强，配方越要向“更多步或蒸馏补偿”一侧偏移，批大小与并发则相应收紧以保住单步时延预算。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-26\">二十六 · 把配方写成可执行的准入规则</h3>\n<p>落到工程上，负载配方应当被写成一组显式的准入规则，而不是散落在配置里的默认值。规则的核心是把请求按（分辨率桶、步数档、CFG 系数组）三元组分类，每类绑定一个批大小上限与一个队列等待阈值。分辨率桶决定 latent 缓存占用，步数档决定 K 步驻留时间，CFG 系数组决定是否启用批合并。三者共同决定单批的显存足迹与时延预算，进而决定并发上限。</p>\n<p>一个可执行的判断是：当某分辨率桶的批形成期等待已经超过单批执行时间的某个比例时，说明该桶的请求到达率撑不起目标批大小，此时应下调该桶的批大小上限而不是无限等待——用小批换低时延，接受单步带宽利用率的部分损失。反之，当某桶长期满批且 P99 时延仍有余量，才考虑上调批大小。这套规则让配方随实际到达率自适应，而不是把 1–8 这个窗口当成固定常量硬编码。</p>\n<p>最后一条规则关于失败回退：当画质抽检发现某类请求（多物体、文字）在 8 步档出现结构错位时，回退路径不是全局加步数，而是按请求类别路由到更高步数档或蒸馏补偿路径，其余请求仍走 8 步配方。这样把直线假设失效的代价限制在少数复杂请求上，而不是让整个服务为它们降速。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-27\">二十七 · 负载配方：直线采样器吃什么样的请求，不吃什么样的</h3>\n<p>整流流直线采样器的性能优势不是无条件成立的，它依赖一类特定的请求形态。最适配的是文生图/图生图的单次 latent 生成：一次请求对应一条从纯噪声 $x_1$ 到样本 $x_0$ 的直线积分，批大小按显存与 SLO 在 1–8 间取，SLO 通常要求单图 8 步内出图。步数从 20 步压到 8 步是常见配置，配合 CFG 批合并——把条件前向与非条件前向拼成一个 batch——把两次前向的开销摊薄到同一批 GEMM 里。此时每步的代价近似为 $T_{\\text{step}} \\approx T_{\\text{GEMM}}(B_{\\text{eff}}) + T_{\\text{attn}}(B_{\\text{eff}}, L)$，其中 $B_{\\text{eff}}$ 是合并后的有效批，$L$ 是 latent 序列长度；总时延 $T = K \\cdot T_{\\text{step}} + T_{\\text{VAE}}$，$K$ 为步数。批内请求长度分布越均匀、分辨率越一致，$B_{\\text{eff}}$ 越能填满，单图摊销成本越低；反之，混合分辨率与混合步数的请求会把 batch 撕成碎片，直线积分的大步长优势被调度开销吃掉。</p>\n<p>负载不对时，失效是分层出现的。第一层是条件复杂度：直线假设在多物体、文字渲染等强约束场景下不严格成立，少步会丢细节，结构错位；这类请求必须回退到更多步或叠加少步蒸馏补偿，SLO 里的 8 步承诺随之作废。第二层是引导强度：CFG 系数在少步下过大会引起过饱和与色彩崩坏，需按步数重调引导强度，这意味着同一模型在不同步数档位上不能共用一套 CFG 配置，调度器必须把步数与 CFG 绑定成请求属性而非全局常量。第三层是积分器选择：二阶中点法每步两次前向，若不做批合并，单图时延反而高于 Euler 大步长配置——二阶降的是离散化误差，不是墙钟时间，误差预算与时间预算在这里是两条独立的账。</p>\n<p>规模上限同样由负载决定。超高分辨率把 latent 序列长度 $L$ 推高，注意力与 latent/timestep embedding 缓存的显存占用按 batch 与分辨率线性增长，单卡放不下时只能切张量并行，通信开销进入关键路径；强文本约束下直线轨迹的弯曲残余需要更多步数消化。因此容量规划应按“分辨率 × 步数 × CFG 是否合并”三维分桶估算吞吐，而不是按单一 QPS 拍脑袋。工程判断很直接：把 4–8 步快速出图、跨模型复用 scheduler 的请求放进直线采样器的主路径，把多物体、文字密集、超高分辨率的请求路由到更多步或蒸馏补偿的慢路径，两条路径共享同一速度场参数化，调度层只做分桶与回退，不做算法切换。</p>\n<table class=\"mini\"><thead><tr><th>请求形态</th><th>适配度</th><th>主要代价</th></tr></thead><tbody><tr><td>单图、均匀分辨率、8 步、CFG 合并</td><td>高</td><td>批填充率决定摊销</td></tr><tr><td>多物体/文字密集</td><td>低</td><td>细节丢失，需加步或蒸馏</td></tr><tr><td>超高分辨率</td><td>中</td><td>显存与带宽，需张量并行</td></tr><tr><td>混合步数/混合 CFG 批</td><td>低</td><td>batch 碎片化，调度开销上升</td></tr></tbody></table>\n<h3 id=\"alg-rectified-flow-sampler-sec-28\">二十八 · 硬件档位与并行拓扑的切分点</h3>\n<p>整流流采样器的部署形态首先由“每步一次 DiT 前向”这一事实决定：Euler 每步一次前向，二阶中点法每步两次前向。因此硬件档位不是按“模型多大”选，而是按“单位时间内能完成多少次完整前向”选。在 Blackwell 上，B200 单卡与 GB200 NVL72 机架是两种典型档位：单卡档位适合 4–8 步、批 1–4 的交互式出图，机架档位适合把批拉到 8 以上、以吞吐换单图时延的服务化部署。</p>\n<p>并行拓扑的切分点在于 DiT 主体的注意力与 GEMM 占比。整流流的速度场网络是标准 DiT 结构，张量并行沿注意力头与 MLP 隐维切分即可覆盖主体；但采样循环本身是串行的——第 k+1 步依赖第 k 步的 latent，无法跨步并行。这意味着并行拓扑只能加速“单步内部”，不能加速“步间”。工程判断是：当单步前向在单卡上已经接近 SLO 预算的 1/8 时，加卡做张量并行收益递减，应转而用批合并摊薄；当单步前向远大于预算时，张量并行是唯一手段。</p>\n<p>一个具体机制：把 timestep embedding 与 CFG 条件编码在采样循环外预计算并常驻，循环内只做 latent 的速度场前向。这样张量并行的通信量集中在注意力与 GEMM 的 all-reduce，而条件侧不参与切分，避免每步重复广播条件张量。代价是显存：条件缓存按批与分辨率线性增长，批 8、高分辨率下这部分常驻显存会挤压 KV（latent 缓存）预算。</p>\n<div class=\"formula\">$$T_{\\text{img}} = N_{\\text{step}} \\cdot \\left( T_{\\text{fwd}}(B) + T_{\\text{comm}}(P) \\right) + T_{\\text{vae}}$$</div>\n<p>其中 $N_{\\text{step}}$ 为 4–8，$B$ 为批，$P$ 为张量并行度。$T_{\\text{comm}}$ 随 $P$ 上升，$T_{\\text{fwd}}$ 随 $P$ 下降，二者交点即最优并行度。中点法把 $N_{\\text{step}}$ 的有效前向次数翻倍，等价于把 $T_{\\text{fwd}}$ 项乘 2，因此中点法配置必须配更大的批或更强的并行，否则单图时延反而高于 Euler 大步长配置——这正是失败模式中“二阶积分不加批合并时延反升”的算术根源。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-29\">二十九 · 量化方案的叠加顺序</h3>\n<p>整流流采样器对量化的敏感点不在单步精度，而在误差沿步累积的方式。直线轨迹下，速度场沿直线恒定，单步量化误差不会被高阶放大，但会在 $N_{\\text{step}}$ 步内线性叠加到末端 latent。因此量化方案的设计目标是：把主体 GEMM 的误差压到不改变末端 latent 分布形态的程度，而不是追求单算子最优。</p>\n<p>叠加顺序建议为：主体 GEMM 走 FP8 或 NVFP4，注意力走 FP8，条件编码与 timestep embedding 保持高精度。理由是条件侧张量在循环外预计算、只算一次，量化它省不下多少时间却直接改变引导方向；而主体 GEMM 每步都跑，是吞吐主项。NVFP4 的块级缩放对 DiT 权重的离群值更友好，但激活侧动态范围在少步大步长下波动更大，需配合分块校准——这部分校准流程属于同模块其他条目的主题，此处只指出：校准必须在“少步、大步长”的实际采样轨迹上做，而非在训练分布上做。</p>\n<p>具体代价：FP8 主体 GEMM 相对高精度把单步前向的算力项减半，显存带宽项也减半，直接抬高批上限；NVFP4 进一步压缩权重常驻显存，使高分辨率下的 latent 缓存有更多余量。但量化误差在 4 步配置下比 8 步配置更危险——步数越少，每步承担的积分区间越大，单步速度场误差被放大的倍数越高。工程判断：4 步配置优先 FP8，8 步配置可上 NVFP4；若必须在 4 步用 NVFP4，则需把 CFG 引导系数按步数下调，避免过饱和与色彩崩坏。</p>\n<table class=\"mini\"><thead><tr><th>档位</th><th>主体 GEMM</th><th>注意力</th><th>条件侧</th><th>适用步数</th></tr></thead><tbody><tr><td>保守</td><td>FP8</td><td>FP8</td><td>高精度</td><td>4–8</td></tr><tr><td>激进</td><td>NVFP4</td><td>FP8</td><td>高精度</td><td>8</td></tr><tr><td>折中</td><td>NVFP4 权重 + FP8 激活</td><td>FP8</td><td>高精度</td><td>6–8</td></tr></tbody></table>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-30\">三十 · KV 策略：latent 缓存与条件缓存的分账</h3>\n<p>整流流采样器没有传统自回归意义上的 KV cache，但有等价物：latent 序列本身在步间被反复读写，条件编码与 timestep embedding 在循环内被反复引用。把这两类缓存分开记账，是部署配方里最容易被忽略的一环。</p>\n<p>latent 缓存按批与分辨率线性增长：批 $B$、分辨率对应的 latent token 数 $L$、精度字节数 $b$，则常驻量为 $B \\cdot L \\cdot b$。它在每步被读一次、写一次，是显存带宽的主要消费者。条件缓存则是 $B \\cdot C$（$C$ 为条件 token 数与嵌入维的乘积），循环外算一次、循环内读 $N_{\\text{step}}$ 次，带宽占比小但常驻占显存。CFG 批合并把条件与非条件前向拼成一个 batch，等价于把 $B$ 翻倍而 $N_{\\text{step}}$ 不变——这部分机制属于同模块 CFG 条目的主题，此处只强调它对 KV 分账的影响：合并后 latent 缓存翻倍，条件缓存不翻倍（两路共享同一份非条件嵌入的只读副本），因此合并的显存代价主要落在 latent 侧。</p>\n<p>具体策略：把 latent 缓存放在高带宽显存池，条件缓存允许被换出到较慢层级，因为它在循环内的访问频率是每步一次而非每算子一次。代价是换出引入的同步点会打断采样循环的流水，若换出发生在步间则影响可控，若发生在步内则直接拉高单步时延。工程判断：批 8、高分辨率下优先保证 latent 常驻，条件缓存按需换出；批 1–4 时两者都可常驻，不必做分账。</p>\n<div class=\"formula\">$$M_{\\text{latent}} = B \\cdot L \\cdot b,\\qquad M_{\\text{cond}} = B \\cdot C \\cdot b,\\qquad M_{\\text{total}} = M_{\\text{latent}} + M_{\\text{cond}} + M_{\\text{weight}}$$</div>\n<p>量化方案直接改写 $M_{\\text{weight}}$ 项，从而决定 $M_{\\text{latent}}$ 的上限；这就是为什么量化与 KV 策略必须联合配置，而不能各自独立调优。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-31\">三十一 · 调度参数：步数、批、引导系数的三角约束</h3>\n<p>调度参数不是三个独立旋钮，而是一个受 SLO 约束的三角：步数决定单图时延的下界，批决定吞吐，引导系数决定少步下的画质稳定性。三者互相挤压，调参顺序应为“先定步数、再定批、最后按步数重调引导系数”。</p>\n<p>步数的选择由 SLO 反推：单图 8 步内出图是常见要求，20 步压到 8 步是常见配置。若 SLO 允许 8 步，则不必上中点法——Euler 大步长在直线轨迹下误差线性累积，8 步已足够；若 SLO 压到 4 步，中点法的两次前向换来的是误差从线性降为二阶，但单步成本翻倍，需用批合并把有效吞吐拉回来。批的选择由显存与 SLO 共同决定，1–8 间取；批越大，单图分摊的固定开销（条件编码、VAE 解码启动）越小，但 latent 缓存线性增长。</p>\n<p>引导系数的重调是少步配置的必要动作：CFG 系数在少步下过大引起过饱和与色彩崩坏，因为少步下每步的引导被放大到更大的积分区间上。具体机制是把引导强度按步数缩放，使总引导量守恒：步数减半时单步引导强度相应下调，避免末端 latent 分布偏移导致 VAE 解码出现色块或结构崩坏。</p>\n<div class=\"formula\">$$x_{k+1} = x_k + \\Delta t\\left[ v_\\theta(x_k,t_k) + w\\left( v_\\theta(x_k,t_k,c) - v_\\theta(x_k,t_k,\\varnothing) \\right) \\right]$$</div>\n<p>其中 $w$ 为引导系数，$c$ 为条件，$\\varnothing$ 为空条件。$w$ 随 $\\Delta t$ 增大而需下调，因为 $\\Delta t \\cdot w$ 才是实际施加的引导位移量。这是可复现配置思路里唯一需要按步数重算的参数。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-32\">三十二 · 一个可复现的配置思路</h3>\n<p>把上述四节收束成一条可复现的配置路径，按以下顺序决策，每步都有明确的判据而非经验值：</p>\n<ul>\n<li>定 SLO：单图时延预算与目标吞吐。若预算落在 8 步 Euler 可满足的区间，锁定 Euler；若预算要求 4 步，锁定中点法并预留两次前向的成本。</li>\n<li>定硬件档位：单步前向时间与预算的比值决定单卡还是张量并行。比值接近 1/8 时单卡加批合并；远大于时上张量并行，并行度取通信与计算交点。</li>\n<li>定量化：按步数选档位。4 步配 FP8 主体，8 步可上 NVFP4；条件侧始终高精度。校准在实际少步轨迹上做。</li>\n<li>定 KV 分账：按批与分辨率算 latent 常驻量，条件缓存按访问频率决定是否换出；CFG 批合并时只翻倍 latent 侧预算。</li>\n<li>定调度：批在 1–8 间取，按显存余量上限；引导系数按步数缩放，使 $\\Delta t \\cdot w$ 守恒。</li>\n<li>验证失败模式：多物体与文字场景下检查细节丢失，若出现结构错位则回退更多步或叠加少步蒸馏；检查末端 latent 分布是否偏移，偏移则下调引导系数或减小步长。</li>\n</ul>\n<p>这条路径的可复现性来自两点：每个决策都有可测量的判据（单步前向时间、显存余量、末端 latent 分布），而非“大概调一调”；参数之间的耦合关系被显式写成公式，改一个参数时能算出对其他参数的连带影响。代价是配置空间被压缩——一旦锁定 4 步中点法，批与并行度的选择余地就变小，因为两次前向已经把单步预算吃满。</p>\n<p>最后落在具体机制上：整流流采样器的部署配方本质是把“直线轨迹带来的大步长容错”兑换成“更少的步数与更小的批”，再用量化与 KV 分账把兑换出来的显存与带宽重新分配给 latent 缓存。兑换率由 $\\Delta t$ 与引导系数的乘积决定，而这个乘积在少步配置下是唯一需要按步数重算的量——把它算对，配置就稳；算错，色块与结构崩坏会直接出现在 VAE 解码的输出上。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-33\">三十三 · 配方边界：直线假设失效处，就是配置要回退的地方</h3>\n<p>这套部署配方的适用域由直线假设的成立程度划定，而非由硬件档位划定。硬件上，单卡或张量并行覆盖 DiT 主体即可，量化叠加 FP8/NVFP4 主体 GEMM 主要压缩权重与激活带宽，对 4–8 步的时延贡献集中在每步前向的 GEMM 时间；真正的边界在条件复杂度：多物体、文字渲染场景下速度场沿直线恒定的前提被破坏，8 步配置开始丢细节、结构错位，此时必须回退到更多步或叠加少步蒸馏补偿，而不能靠加卡或换精度救回。KV 在这里指 latent 与 timestep embedding 缓存，按 batch 与分辨率线性增长，是显存预算里随分辨率上升最快的一项，超高分辨率下它先于权重成为瓶颈。</p>\n<p>步数与每步开销的权衡可用一个简单代价式判断：设单次前向时延为 <span class=\"formula\">$$T_{\\text{img}}\\approx N_{\\text{step}}\\cdot c\\cdot T_{\\text{fwd}}(B)+T_{\\text{vae}}$$</span> 其中 Euler 取 c=1、二阶中点法取 c=2，B 为批大小。中点法把离散化误差压低，但单图、未做 CFG 批合并时 c=2 直接让时延翻倍，反而劣于 Euler 大步长配置；只有把条件与非条件前向拼成一个 batch 摊薄开销后，二阶积分才在同等 SLO 下划算。批大小按显存与 SLO 在 1–8 间取，SLO 通常要求单图 8 步内出图，20 步压到 8 步是常见落点。</p>\n<p>失效条件要写进调度参数而不是留给现场调参：CFG 引导系数在少步下过大会引起过饱和与色彩崩坏，需按步数重调引导强度，步数越少、系数上限越低；步长过大时末端 latent 分布偏移，VAE 解码出现色块或结构崩坏，这是积分器与步数不匹配的直接症状，应优先加密时间点而非降精度。可复现的配置思路因此是三层判定：先按场景复杂度定步数档（简单场景 4–8 步 Euler，复杂条件回退更多步或蒸馏），再按 SLO 与显存定 batch 与是否启用中点法，最后才选量化档位；量化只影响每步成本，不改变直线假设的成立边界。</p>\n<table class=\"mini\"><thead><tr><th>失效信号</th><th>归因</th><th>配方动作</th></tr></thead><tbody><tr><td>文字/多物体细节丢失</td><td>直线假设不成立</td><td>增步或叠加少步蒸馏</td></tr><tr><td>单图时延高于 Euler</td><td>中点法两次前向未合并</td><td>CFG 批合并或退回 Euler</td></tr><tr><td>过饱和、色彩崩坏</td><td>少步下 CFG 系数过大</td><td>按步数下调引导强度</td></tr><tr><td>色块、结构崩坏</td><td>步长过大、末端分布偏移</td><td>加密时间点，勿降精度</td></tr></tbody></table>\n<h3 id=\"alg-rectified-flow-sampler-sec-34\">三十四 · 单图时延的构成：步数乘以每步前向，再乘以批的空转</h3>\n<p>整流流采样器把推理时延拆成三个可独立调节的乘子：步数 $K$、每步前向次数 $n_f$（Euler 为 1，二阶中点为 2）、以及每步前向在给定 batch 下的实际执行时间。单请求端到端时延可写成</p>\n<div class=\"formula\">$$T_{\\text{e2e}} \\approx K \\cdot n_f \\cdot \\big(T_{\\text{GEMM}}(B,H,W) + T_{\\text{attn}}(B,H,W)\\big) + T_{\\text{VAE}}$$</div>\n<p>其中 $B$ 是 CFG 合并后的有效批，$H,W$ 是 latent 分辨率。工程上真正决定 SLO 的不是 $K$ 本身，而是 $K \\cdot n_f$ 与 $B$ 的耦合：当 $B=1$ 时，DiT 主体 GEMM 的 M 维只有 1，SM100 的 tcgen05 MMA 在 M 方向填不满，tensor core 利用率被压到很低，此时每步时间由权重带宽主导而非算力主导；把 CFG 的条件与非条件前向拼进同一 batch（前文已述的批合并）正是为了把 $B$ 抬到 2 以上，让每步从“搬权重”变成“算矩阵”。因此“20 步压到 8 步”的收益并非线性：8 步配 $B=2$ 的合并批，与 20 步配 $B=1$ 的串行前向相比，前者的墙钟时间下降幅度大于步数比 2.5，因为后者每步都在浪费 MMA 的 M 维。中点法把 $n_f$ 从 1 提到 2，若不同时扩大批，单图时延会直接翻倍——这是部署配方里“按步数与每步开销权衡”的具体含义：二阶积分只在批已经足够大、每步已接近算力瓶颈时才划算，否则应退回 Euler 大步长。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-35\">三十五 · 显存与带宽：latent 缓存、timestep embedding 与权重驻留</h3>\n<p>整流流采样器的显存账目比自回归推理简单，因为没有随序列增长的 KV cache，但有三个随配置变化的项：latent 工作集、timestep embedding 与条件嵌入、以及 DiT 权重。latent 工作集按 $B \\times C \\times H \\times W \\times$ dtype 计，FP8 下每元素 1 字节，NVFP4 下约 0.5 字节；一个 $1024\\times1024$ 图像在 8 倍下采样的 latent 是 $128\\times128$，$C=16$ 时单张 FP8 latent 约 256 KB，8 张合并批不到 2 MB——latent 本身不是瓶颈，瓶颈在中间激活。DiT 的注意力与 MLP 中间张量按 token 数 $\\times$ 隐藏维 $\\times$ 层数峰值计，高分辨率下 token 数随 $H \\cdot W$ 平方增长，激活峰值往往比权重更早触顶。timestep embedding 每步重算，$B$ 小的时候它是一次小 GEMM，$B$ 大时它与条件嵌入一起构成不可忽略的常量开销。</p>\n<p>带宽侧的关键判断是：采样器每步都要把全部 DiT 权重从 HBM 读一遍（除非权重能驻留在 L2 或分片驻留）。单步权重流量约等于模型参数量 $\\times$ 每参数字节，FP8 下比 BF16 减半，NVFP4 下再减半。当 $B$ 很小时，每步时间 $\\approx$ 权重字节 / HBM 带宽，这就是“带宽受限区”；当 $B$ 增大到算术强度超过机器平衡点后转入“算力受限区”。Blackwell 的 HBM 带宽相对其 tensor core 算力而言，平衡点对应的 $B$ 并不低，因此少步采样在低批下天然落在带宽受限区——这解释了为什么单纯压步数在单请求场景收益有限，而必须靠批合并或连续批处理把 $B$ 抬起来。规模上去以后，第一个崩的通常不是算力而是 HBM 带宽：并发请求一多，每步权重流量乘以并发批次数，带宽被吃满，步数再少也压不下时延。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-36\">三十六 · 通信：张量并行下的每步 all-reduce 与分离式部署的 latent 搬运</h3>\n<p>当 DiT 主体跨卡张量并行时，每个采样步内每层都有一次 all-reduce（或 reduce-scatter + all-gather），通信量与 $B \\times$ token 数 $\\times$ 隐藏维成正比，且每步都要发生 $K \\cdot n_f$ 次。这意味着通信开销随步数线性叠加，而单次通信的固定延迟（kernel launch、NVLink 5 上的同步）在小 batch 下占比很高。张量并行度 $P$ 增大时，单卡权重分片变小、每步计算变短，但 all-reduce 的参与方变多、单次延迟上升；存在一个 $P$ 使每步时间最小，超过它通信主导。对 4–8 步的少步配置，每步的计算窗口本就很短，通信的固定开销更容易吃掉并行收益——这是少步采样与高张量并行度之间的结构性矛盾，工程上倾向用较小的 $P$ 配合更大的批，而不是用大 $P$ 去压单步时延。</p>\n<p>分离式预填/解码在扩散场景里对应的是“条件编码与 latent 生成分离”：文本编码器、VAE 编码器可以放在独立进程或独立卡上，latent 采样在另一组卡上跑。此时每步不产生跨节点通信，但请求边界上要搬运条件嵌入与末端 latent。末端 latent 送 VAE 解码的搬运量按 $B \\times C \\times H \\times W$ 计，高分辨率下这一跳的字节数不可忽略，若跨节点则要走 NIXL 之类的传输路径，其延迟会计入尾延迟而非均值。规模上去后，第二个崩的往往是请求边界的搬运与排队：采样本身是短时突发，条件编码与 VAE 解码是长尾，二者节奏不匹配会在队列里堆积。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-37\">三十七 · 功耗与热：少步高批把能量密度推到峰值区间</h3>\n<p>整流流少步采样的功耗特征与常规推理相反：它不是长时间低占空比运行，而是把 $K \\cdot n_f$ 次前向压进很短的墙钟窗口，每步都是满血的 GEMM + 注意力。功耗近似正比于“活跃 SM 数 $\\times$ 每 SM 的 MMA 吞吐”，在算力受限区，$B$ 越大、每步越接近峰值功耗；在带宽受限区，功耗由 HBM 读写主导，相对低但持续时间被拉长。总能量可写成</p>\n<div class=\"formula\">$$E \\approx \\sum_{k=1}^{K}\\big(P_{\\text{compute},k} \\cdot \\tau_{\\text{compute},k} + P_{\\text{mem},k} \\cdot \\tau_{\\text{mem},k}\\big)$$</div>\n<p>少步配置把 $K$ 压小，但每步的 $\\tau$ 因批增大而变长，总能量未必下降——省的是固定开销与权重重复搬运，不是峰值功率。机架级（GB200 NVL72）部署时，多卡同时进入采样峰值会造成瞬时功率尖峰，若电源与散热按均值设计就会触发降频，降频又反过来拉长每步时间、破坏 SLO。工程判断是：把采样请求在时间上错峰（连续批处理天然做这件事），并给峰值功率留出裕度，而不是靠提高步数去“摊平”功耗——后者只会增加总能量。规模上去后，第三个崩的常是功耗墙而非算力墙，尤其在机架密度高的部署里。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-38\">三十八 · 尾延迟：步长过大导致的回退与重采样</h3>\n<p>少步采样的尾延迟来源不是均值抖动，而是失败模式触发的重试。直线假设在多物体、文字渲染等复杂条件下不严格成立，8 步下细节丢失或结构错位；步长过大时末端 latent 分布偏移，VAE 解码出现色块或结构崩坏。服务侧若检测到这类输出（或上游质量门控拒绝），就要回退到更多步重采样，单请求时延从 8 步跳到 20 步量级，且这次重采样落在尾部分布上。尾延迟因此呈现双峰：大部分请求走 8 步快路径，少数请求走 20 步慢路径，P99 由慢路径决定。CFG 引导系数在少步下过大引起过饱和，是另一类触发重采样的失败模式，需按步数重调引导强度而非沿用 20 步的系数。</p>\n<p>控制尾延迟的机制是分级步数策略：按条件复杂度（提示词长度、是否含文字、参考图数量）预判所需步数，把 4–8 步分配给简单条件，把更多步留给复杂条件，而不是让所有请求共享同一 $K$。这与“步数一降画质就崩”的原始问题同源，但解法从算法侧（拉直轨迹）转到系统侧（按请求分流）。代价是调度器要维护两套步数配置与两套批形状，连续批处理在混合步数请求间切换时会产生批重组开销；若重组频繁，尾延迟的改善会被批碎片化抵消。规模上去后，第四个崩的是调度粒度：请求异质性越高，统一批越难维持，尾延迟与吞吐的权衡越尖锐。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-39\">三十九 · 规模上限的排序：带宽、功耗、通信、调度的先后</h3>\n<p>把上述代价按规模增长的敏感度排序，可以得到一条工程判断链。并发从 1 涨到几十时，最先触顶的是 HBM 带宽（每步权重流量 $\\times$ 并发批），表现为每步时间随 $B$ 线性上升而非持平；继续加并发，功耗进入峰值区间并触发降频，每步时间二次恶化；跨卡张量并行度提高后，all-reduce 的固定延迟在少步短窗口里占比上升，通信成为第三道墙；最后是请求异质性带来的调度碎片化，尾延迟无法靠加卡解决。这条链的实践含义是：扩容时优先加批（提高算术强度、摊薄权重流量），其次错峰（压功耗尖峰），再次才是加并行度；而尾延迟要靠请求分流而非资源堆叠。</p>\n<table class=\"mini\"><thead><tr><th>规模阶段</th><th>先崩的资源</th><th>可观测信号</th><th>对应机制</th></tr></thead><tbody><tr><td>单请求、低批</td><td>HBM 带宽</td><td>每步时间≈权重字节/带宽，$B$ 增大时间不变</td><td>权重每步重读，MMA 的 M 维填不满</td></tr><tr><td>中等并发</td><td>功耗/散热</td><td>采样峰值触发降频，每步时间抖动</td><td>$K \\cdot n_f$ 次满血前向压进短窗口</td></tr><tr><td>高张量并行</td><td>NVLink 通信</td><td>单步时间随 $P$ 先降后升</td><td>每步 all-reduce，固定延迟占比高</td></tr><tr><td>高异质性</td><td>调度粒度</td><td>P99 双峰，批重组频繁</td><td>分级步数与混合批形状切换</td></tr></tbody></table>\n<p>具体例子：一个 8 步、$B=2$（CFG 合并）的配置在单卡上每步落在带宽受限区，把并发提到 8 个请求、批扩到 16 后转入算力受限区，每步时间不再随批线性增长，吞吐提升幅度大于批比；此时若再叠加张量并行度 4，每步 all-reduce 的固定延迟会吃掉部分收益，净时延可能不降反升。正确的做法是保持 $P=1$ 或 $P=2$、把批继续做大，直到功耗墙出现，再用错峰调度压峰值。末端 latent 送 VAE 的那一跳在高分辨率下也要计入：VAE 解码是长尾，若与采样共用卡，采样峰值与解码峰值叠加会加剧降频，分离式部署在这里的价值是把两类峰值在时间与空间上解耦。规模上去以后哪里先崩，答案取决于当前落在哪个区；判断依据是每步时间随 $B$ 的斜率——斜率为正且接近线性，说明还在带宽区，加批是唯一有效手段。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-40\">四十 · 规模上升后的首个瓶颈：从算力墙到带宽墙</h3>\n<p>单卡、批大小 1–8、8 步出图的配置里，整流流采样器的代价几乎全落在 DiT 主体的 GEMM 上，FP8/NVFP4 量化能直接把它压下去。但批一放大、分辨率一抬，瓶颈就换位置了：每步前向要读的权重是固定的，激活与 latent 却随 batch×分辨率线性涨，KV（latent 与 timestep embedding 缓存）同步膨胀。此时单步时延不再由算力决定，而由显存带宽与容量决定——权重读一遍的时间被摊薄后，激活写回与 attention 的访存成了主项。Euler 每步一次前向尚可，二阶中点法每步两次前向，等于把带宽压力直接乘二，批越大越不划算。</p>\n<div class=\"formula\">$$T_{\\text{img}}\\approx \\frac{S\\cdot \\left(2\\,W_{\\text{bytes}}+B\\,A_{\\text{bytes}}\\right)}{\\text{BW}_{\\text{eff}}}+S\\cdot t_{\\text{launch}},\\quad S\\in\\{4,\\dots,8\\}$$</div>\n<p>式子里 $S$ 是步数、$W$ 是主体权重字节、$B$ 是批、$A$ 是单样本激活字节。它说明一个工程判断：当 $B\\cdot A$ 逼近 $2W$ 时，加批不再线性摊薄成本，吞吐曲线开始走平；再往上加，显存先满而不是算力先满。张量并行能切开权重、缓解单卡容量，但每步都要 all-reduce 激活，NVLink 5 上的通信量与 $B$ 成正比，跨节点时通信延迟会直接进入每步的关键路径，8 步就是 8 次同步点，尾延迟被放大成 $S$ 倍抖动。</p>\n<h3 id=\"alg-rectified-flow-sampler-sec-41\">四十一 · 尾延迟与失效条件：少步把误差集中到末端</h3>\n<p>步数压到 4–8 后，单图时延的均值好看，尾延迟却更难看：请求在批里排队，一个 batch 的完成时间由最慢的那次前向决定，而少步配置没有多余的步去“吸收”一次慢迭代。更关键的是失效条件——直线假设在多物体、文字渲染下不严格成立，步长过大时末端 latent 分布偏移，VAE 解码出色块或结构崩坏；CFG 系数在少步下过大会过饱和。这些不是随机抖动，而是随分辨率与文本约束强度单调恶化的系统性误差，规模上去后表现为返工率上升而非单图变慢。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先崩的资源</th><th>表现</th></tr></thead><tbody><tr><td>批大小↑</td><td>显存容量 / 带宽</td><td>吞吐走平，OOM 先于算力饱和</td></tr><tr><td>分辨率↑</td><td>激活带宽、attention</td><td>单步时延非线性涨，末端结构错位</td></tr><tr><td>张量并行↑</td><td>NVLink 通信</td><td>每步同步点 ×S，尾延迟抖动放大</td></tr><tr><td>步数↓至 4</td><td>画质余量</td><td>文字/多物体细节丢失，需蒸馏补偿</td></tr></tbody></table>\n<p>因此容量规划不能只按平均吞吐算卡数，要按“8 步 × 最慢 batch”的尾延迟定 SLO 余量；跨模型复用 scheduler 带来的工程简化，换不来直线假设在强约束场景下的误差豁免——超高分辨率与强文本约束要么回退更多步，要么叠加少步蒸馏，代价是训练期投入与额外的教师依赖，这笔账要在规模扩张前先算清。</p>\n<h3 id=\"alg-rectified-flow-sampler-sec-42\">四十二 · 精度失效的三条路径与定位手段</h3>\n<p>整流流采样器在 Blackwell 上的精度问题不会以“报错”的形式出现，它表现为末端 latent 的分布偏移，再经 VAE 解码放大成色块、过饱和或结构错位。三条典型路径需要分开定位：其一是直线假设本身失效，多物体与文字渲染条件下速度场不再沿直线恒定，Euler 大步长把这种弯曲直接积分成结构错位；其二是数值精度叠加，FP8/NVFP4 主体 GEMM 的量化误差在 4–8 步的短积分链上缺少后续步的自我修正机会，误差单调累积而非振荡抵消；其三是 CFG 引导系数与步数不匹配，少步下过大的引导强度把条件分支的速度场外推到训练分布之外，末端 latent 越界。</p>\n<p>区分三者靠的是把积分链拆开看，而不是只看最终出图。工程上在每步 $t_k$ 落一次 latent 的统计量：均值、方差、以及相邻两步的速度场余弦相似度。直线轨迹成立时，$v_\\theta(x_k,t_k)$ 与 $v_\\theta(x_{k+1},t_{k+1})$ 应高度同向；余弦相似度在某个 $k$ 处骤降，说明该步跨过了直线假设的断裂点，属于路径一。若余弦相似度平稳但 latent 方差随步数单调漂移，则是量化误差累积，属于路径二。若仅在 CFG 打开时方差爆炸、关闭 CFG 后恢复正常，属于路径三。</p>\n<div class=\"formula\">$$\\cos_k=\\frac{\\langle v_\\theta(x_k,t_k),\\,v_\\theta(x_{k+1},t_{k+1})\\rangle}{\\|v_\\theta(x_k,t_k)\\|\\,\\|v_\\theta(x_{k+1},t_{k+1})\\|},\\qquad \\Delta\\mathrm{var}_k=\\mathrm{Var}(x_{k+1})-\\mathrm{Var}(x_k)$$</div>\n<p>代价在于诊断本身要额外前向或至少保留中间 latent。若在 8 步链上每步都落盘 latent，按 1024×1024 分辨率、latent 通道数与批大小 4 计，中间缓存会与 KV/latent 缓存同量级增长，直接吃掉本已紧张的显存预算；折中做法是只落 $k=0,2,4,6,7$ 五个点，并在关闭 CFG 的旁路上跑一次对照，用一次额外前向换掉整条链的落盘。具体例子：文字渲染请求在 8 步配置下出现字形糊化，把同一 prompt 用 20 步重跑后消失，且第 4 步余弦相似度已跌到明显低于前几步——判定为路径一，处置是回退步数或叠加少步蒸馏，而不是调量化。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-43\">四十三 · OOM 的真实来源与回收顺序</h3>\n<p>整流流采样器的 OOM 很少来自 DiT 主体权重，更多来自三处叠加：CFG 批合并把条件与非条件前向拼成一个 batch，使激活峰值翻倍；二阶中点法每步两次前向，若中间量未及时释放，峰值再叠一层；高分辨率下的 latent 与 timestep embedding 缓存按 batch 与分辨率线性增长。三者同时打开时，峰值激活往往比稳态高出数倍，而稳态显存看起来还很宽裕，于是 OOM 出现在第 2–3 步而非第 0 步。</p>\n<p>回收顺序应当是确定的，不能靠框架的自动回收碰运气：先释放上一步的速度场输出（Euler 只需当前步的 $v$，中点法只需半步预测与校正两次），再释放 CFG 非条件分支的中间激活（条件分支的 K/V 若被缓存则保留），最后才动 latent 缓存。伪代码思路是显式作用域：</p>\n<div class=\"formula\">$$\\text{peak}\\approx B\\cdot\\bigl(c_{\\text{latent}}(H,W)+2\\,c_{\\text{act}}\\bigr)+c_{\\text{weight}},\\qquad B_{\\text{cfg}}=2B$$</div>\n<p>其中 $B_{\\text{cfg}}$ 是合并后的有效批，$c_{\\text{act}}$ 是单次前向的激活。工程判断是：在 B200 单卡上把批大小按“CFG 合并后”的有效批来算，而不是按用户请求数算；请求批 4 在 CFG 合并后等价于批 8 的激活。具体例子：批 8 的图生图请求在开启 CFG 与中点法时于第 2 步 OOM，把批降到 4 并改为 Euler 后通过，吞吐下降但 SLO 内的单图时延反而更稳——因为中点法的两次前向在单图场景下把时延推高，批合并摊薄不了这笔开销。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-44\">四十四 · 批抖动与路由不均的耦合</h3>\n<p>批抖动在整流流服务里表现为同一批内不同请求的步数不同：有的走 4 步，有的因回退走 8 步，有的因 CFG 关闭走单分支。连续批处理按 token 或按步调度时，短步请求提前退出会让批的有效规模在积分链中途塌陷，GPU 利用率出现锯齿。更麻烦的是路由不均：多副本部署下，若路由器按请求到达顺序轮询而不看当前批占用，长步请求会持续堆到同一副本，形成“一个副本 8 步满载、另一个副本 4 步空转”的偏斜。</p>\n<p>机制上要把步数作为调度的一等公民：入队时按请求的步数档位打标，调度器优先把同档位请求拼批，跨档位拼批只在批未满时作为填充；路由侧用副本的“剩余步数工作量”而非请求计数做加权。代价是拼批灵活性下降，短步请求可能等不到同档位伙伴而单独成批，单批利用率降低；收益是积分链中途塌陷减少，尾延迟方差收窄。具体例子：混合负载下 4 步与 8 步请求各半，按到达顺序拼批时批规模在第 4 步后腰斩，按档位拼批后每批走完全程，吞吐与尾延迟同时改善，代价是 4 步请求的平均排队时间上升——这是可接受的，因为它的单图时延预算更宽。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-45\">四十五 · 尾延迟尖刺的四个来源</h3>\n<p>尾延迟尖刺在整流流采样器上有明确的来源清单，逐个封堵比笼统加超时有效。第一是步数回退：精度诊断触发回退到更多步，单请求时延按步数线性放大，若回退发生在批内，整批被拖长。第二是二阶积分的两次前向在批未满时无法摊薄，单图时延高于 Euler 配置。第三是 VAE 解码的分块并行在末端 latent 分辨率跳变时出现块间等待，解码阶段的长尾盖过采样阶段。第四是跨副本的 latent 缓存未命中，请求被路由到没有缓存的副本，重新计算 timestep embedding 与条件编码。</p>\n<p>监控上对每个来源设独立的分位指标，而不是只看端到端 P99：采样阶段按步数分桶统计 P99，解码阶段单独统计，缓存命中率按副本统计。判定阈值用相对量而非绝对量——某副本的采样 P99 相对集群中位数抬升超过一个可辨幅度，即触发路由权重下调。具体例子：某副本因显存碎片导致 VAE 分块并行退化为串行，解码 P99 抬升而采样 P99 正常，端到端 P99 被解码段主导；若只看端到端会误判为采样问题而去调步数，实际处置是把该副本摘出重排显存或重启。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-46\">四十六 · 监控埋点与回滚的工程约束</h3>\n<p>监控埋点必须落在积分链的边界上，而不是散落在算子内部。三个必埋点：每步 latent 的均值方差与速度场余弦相似度（精度诊断）、每批的有效批规模随步数的变化曲线（批抖动）、每副本的步数档位分布与缓存命中率（路由不均）。埋点开销要可控，统计量用低精度累加即可，避免为监控再开一条高精度前向。代价是每步多一次归约，在 8 步链上摊薄后对吞吐影响有限，但在 4 步链上占比上升，需按步数档位决定是否全量埋点。</p>\n<p>回滚策略要按失败模式分级，而不是一刀切回上一版本。精度类失败优先回滚步数配置（8 步回 20 步）或关闭 CFG 批合并走单分支，因为这类回滚不涉及权重与量化格式，切换成本最低；OOM 类失败优先回滚批大小与积分方法（中点法回 Euler），再考虑降分辨率；批抖动与路由类失败回滚调度策略与路由权重，不动模型侧。回滚的判定要自动化：连续若干个批次的精度统计量越界、或 OOM 重试率超过阈值，即触发配置回滚，并把触发时的 latent 统计量留存供离线复现。</p>\n<p>具体机制上，把步数、积分方法、CFG 系数、批大小、量化格式打包成一个可版本化的“采样配置”，与请求一起记录，回滚即切换配置指针而非重新部署。这样做的工程判断是：整流流的 scheduler 可跨模型复用，配置本身也应跨副本复用，回滚的粒度是配置而非镜像，才能在尾延迟尖刺出现的秒级窗口内完成切换。代价是配置组合爆炸需要治理，只允许经过验证的少数组合进入可回滚集合，其余组合仅用于离线实验。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-47\">四十七 · 直线采样器的失效边界与在线诊断</h3>\n<p>整流流在 4–8 步量级维持画质的前提，是速度场沿直线恒定这一假设在给定条件 $c$ 下近似成立。当条件复杂——多物体相互遮挡、文字笔画、细密纹理——真实概率路径的条件期望速度 $\\mathbb{E}[v_\\theta(x_t,t)\\mid c]$ 沿 $t$ 出现非单调漂移，直线假设被打破，Euler 大步长把这种漂移一次性外推，误差不再随步长线性收敛。诊断上不要只看整图 FID 类指标，应在固定种子下做步数扫描：对同一 prompt 分别跑 8 步与 20 步，逐像素比较末端 latent 与解码图，若 8 步结果在文字区域出现笔画断裂、在多物体交界出现结构错位，即为直线假设失效的典型信号。此时的处理不是调 scheduler，而是回退步数或叠加少步蒸馏补偿；把 8 步硬扛到所有 prompt 上，等于用画质换吞吐，且失败样本的分布高度集中在长 prompt 与高分辨率档。</p>\n<p>精度问题在少步下被放大，根源是末端 latent 分布偏移。Euler 更新 $x_{k+1}=x_k+\\Delta t\\,v_\\theta(x_k,t_k)$ 的截断误差正比于 $\\Delta t^2\\cdot\\|\\partial_t v\\|$，步数从 20 压到 8 意味着 $\\Delta t$ 放大约 2.5 倍，误差放大约 6 倍；若再叠加 FP8/NVFP4 主体 GEMM，量化噪声与截断误差同量级叠加，VAE 解码端就表现为色块、饱和度爆表和局部结构崩坏。二阶中点法把局部误差降到 $\\Delta t^3$ 量级，但每步两次前向，单图时延在未做 CFG 批合并时反而高于 Euler 大步长配置——这是典型的“精度换时延”权衡点，必须按 SLO 显式选择，而不是默认开中点法。CFG 引导系数在少步下过大同样触发过饱和：引导强度放大了条件与非条件速度场之差，而少步积分没有足够时间把这个偏差拉回，需按步数重调系数，8 步配置的引导强度应低于 20 步配置。</p>\n<p>系统侧的失败模式与采样器本身无关，却常被误诊为画质问题。批抖动来自批大小在 1–8 间按显存与 SLO 动态取值：CFG 批合并把条件与非条件前向拼成一个 batch，若合并后 batch 跨越显存水位线触发重分配，单图时延出现周期性尖刺；路由不均则出现在张量并行覆盖 DiT 主体时，各 rank 的 latent 与 timestep embedding 缓存按 batch 与分辨率线性增长，分辨率切换导致某 rank 先撞上限，尾延迟尖刺随之出现。监控应分层：请求级记录步数、CFG 系数、分辨率、批大小与端到端时延；设备级记录显存水位、SM 利用率与 GEMM 有效算力；采样级在固定种子下抽样比对 8 步与参考步数的 latent 距离。回滚策略按粒度分级——单请求级回退到 20 步或关闭中点法，服务级回退到上一版 scheduler 与量化档位，集群级摘除异常 rank。下表给出诊断信号与对应动作的映射。</p>\n<table class=\"mini\"><thead><tr><th>信号</th><th>最可能成因</th><th>动作</th></tr></thead><tbody><tr><td>文字/多物体区域结构错位</td><td>直线假设失效，步数不足</td><td>该 prompt 回退 20 步或叠加蒸馏</td></tr><tr><td>色块、过饱和</td><td>CFG 系数过大 + 量化噪声</td><td>按步数下调引导强度，回退 FP8→BF16 主体</td></tr><tr><td>周期性单图时延尖刺</td><td>CFG 批合并跨显存水位</td><td>固定批大小上限，关闭动态合并</td></tr><tr><td>某 rank 尾延迟持续偏高</td><td>缓存按分辨率线性增长，路由不均</td><td>按分辨率分池路由，摘除异常 rank</td></tr></tbody></table>\n<h3 id=\"alg-rectified-flow-sampler-sec-48\">四十八 · 同族谱系与选型的第一性判据</h3>\n<p>把整流流放回采样器家族里看，选型不是“谁更先进”，而是“谁的误差结构匹配你的步数预算”。DDPM/DDIM 的轨迹弯曲，离散化误差随步长以高阶项累积，步数一砍就崩；一致性模型把多步压成一步，代价是必须依赖教师模型做蒸馏，训练侧耦合重；整流流则是在训练期重参数化概率路径，把插值拉成直线，让 Euler 大步长的局部截断误差退化为沿直线的一阶残差。因此第一判据是：<strong>你的 SLO 步数落在哪个区间</strong>。落在 4–8 步且要求 scheduler 跨模型复用，整流流是默认解；落在 1–2 步且已有高质量教师，走一致性蒸馏；落在 20 步以上且模型与 scheduler 已绑定死，继续用 DDIM 反而省去改造训练管线的工程成本。</p>\n<p>第二判据是<strong>是否允许改训练</strong>。整流流不是纯推理侧技巧，它要求模型在直线插值上回归恒定速度场，监督目标为 $v=x_1-x_0$。若你手上只有开放权重的 DDIM 检查点、无法重训，整流流不能直接套用，只能靠少步蒸馏近似；反之若你在做自有模型的推理部署，训练期重参数化是一次性成本，换来的 scheduler 可跨模型复用是长期收益。第三判据是<strong>条件复杂度</strong>：直线假设在多物体、文字渲染下不严格成立，这类负载要么回退更多步，要么叠加蒸馏补偿，选型时必须把这条写进容量规划的余量里。</p>\n<div class=\"formula\">$$\\text{选型判据}:\\quad \\arg\\min_{a\\in\\{\\text{RF},\\text{CM},\\text{DDIM}\\}}\\ \\underbrace{N_{\\text{step}}(a)\\cdot C_{\\text{fwd}}(a)}_{\\text{单图时延}}+\\lambda\\cdot\\underbrace{E_{\\text{detail}}(a)}_{\\text{画质惩罚}}$$</div>\n<p>其中 $N_{\\text{step}}$ 是满足画质下限所需步数，$C_{\\text{fwd}}$ 是每步前向成本（中点法为两次前向，Euler 为一次），$E_{\\text{detail}}$ 是复杂条件下的细节损失。工程上这个式子不能解析求解，但可以用小批量探针在目标分辨率与提示词分布上实测三个候选的时延-画质曲线，把 $\\lambda$ 标定成业务可接受的画质折损单价。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-49\">四十九 · 决策表：四类负载的映射</h3>\n<p>下表把常见推理负载映射到同族算法，列的是适用条件而非绝对优劣。注意“步数”列是满足 SLO 的配置区间，不是算法上限。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>首选</th><th>步数配置</th><th>关键代价</th><th>回退条件</th></tr></thead><tbody>\n<tr><td>通用文生图，提示词中等复杂度</td><td>整流流 + Euler</td><td>8 步（20→8 压缩）</td><td>单次前向，时延最低</td><td>文字渲染崩坏时加步或叠蒸馏</td></tr>\n<tr><td>强文本/多物体构图</td><td>整流流 + 中点法</td><td>8–12 步</td><td>每步两次前向，单步成本翻倍</td><td>仍丢细节则回退 DDIM 20 步</td></tr>\n<tr><td>极低时延（交互式预览）</td><td>一致性蒸馏</td><td>1–2 步</td><td>依赖教师，训练侧耦合</td><td>无教师则不可用</td></tr>\n<tr><td>存量 DDIM 检查点、不可重训</td><td>DDIM 原 scheduler</td><td>20 步以上</td><td>scheduler 绑定，跨模型不可复用</td><td>可加特征缓存跳步降本</td></tr>\n</tbody></table>\n<p>表里最容易被误读的是第二行：中点法不是“更准所以更好”，它的价值只在直线假设开始失效的区间才兑现。若提示词分布简单，Euler 8 步与中点法 8 步画质差异落在噪声内，此时中点法的两次前向纯属浪费，单图时延反而高于 Euler 大步长配置——这正是失败模式里点名的陷阱。选型动作应是：先用 Euler 跑目标分布，统计细节丢失率，超过阈值再切中点法，而不是默认上二阶。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-50\">五十 · 与一致性模型的边界：蒸馏 vs 重参数化</h3>\n<p>整流流与一致性模型常被并列讨论，但二者压步数的机理完全不同。一致性模型靠蒸馏把多步轨迹映射到一步，推理时一次前向出图，代价是训练阶段必须有教师模型生成轨迹、且学生模型与教师绑定；整流流是训练期重参数化路径，不依赖教师，速度场形式统一，scheduler 可跨模型复用。工程含义是：<strong>一致性模型的压步上限更高，但可维护性更差</strong>；整流流的 4–8 步不是理论下限，而是直线假设下画质稳定的经验区间，再往下压需要叠加少步蒸馏，此时两者在推理侧收敛到相似的步数，区别退化为“你是否愿意维护教师-学生链路”。</p>\n<p>一个具体判断：若你的模型每季度换一次底座，整流流的统一速度场参数化让 scheduler 跟着模型走而不用重训蒸馏链路，运维成本低；若你的底座冻结、只追求极致时延，一致性蒸馏的一次前向在同样硬件上把单图时延压到整流流 8 步的几分之一，代价是教师链路成为单点。混合策略也成立：整流流主干跑 8 步保证通用画质，对高价值请求叠加蒸馏出 2 步草稿做投机式预览，这属于投机解码思路在扩散采样上的移植，选型时把它当作“整流流 + 蒸馏”的组合项而非二选一。</p>\n<div class=\"formula\">$$\\text{压步收益}:\\quad \\frac{T_{\\text{RF}}(8)}{T_{\\text{CM}}(1)}=\\frac{8\\,C_{\\text{fwd}}^{\\text{Euler}}}{1\\,C_{\\text{fwd}}^{\\text{CM}}}\\approx 8\\cdot\\frac{C_{\\text{fwd}}^{\\text{Euler}}}{C_{\\text{fwd}}^{\\text{CM}}}$$</div>\n<p>该比值说明：一致性模型单步前向若与 Euler 单步同量级，时延差就是步数比；但 CM 单步往往因结构差异略贵，实际比值小于 8。选型时不要用步数比直接外推时延，要在目标硬件上实测 $C_{\\text{fwd}}$ 两项。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-51\">五十一 · 与 DDIM 的边界：scheduler 复用性的工程价值</h3>\n<p>DDIM 的 scheduler 与模型绑定，换模型就得重调 $\\beta$ 序列与跳步策略，这在多模型混布的推理集群里是实打实的运维负担。整流流用统一速度场参数化，$t\\in[0,1]$ 上的离散时间点与模型解耦，同一套 Euler/中点积分器可以跨模型复用，工程实现简单到几乎只是一段定步长循环。代价是直线假设在复杂条件下不严格成立，少步丢细节，需要用步数或蒸馏补偿。选型判断因此落在“模型数量 × 换模型频率”上：单模型长期冻结，DDIM 的绑定劣势不显现；多模型、快迭代的集群，整流流的 scheduler 复用价值随模型数线性放大。</p>\n<p>另一个常被忽略的代价项是<strong>末端 latent 分布偏移</strong>。步长过大时，Euler 积分累积的残差让末端 latent 偏离训练分布，VAE 解码出现色块或结构崩坏。DDIM 在高步数下轨迹弯曲但末端分布更贴训练流形，这也是为什么“回退 DDIM 20 步”在表里是合法回退项而非倒退。工程上应把末端 latent 的统计量（均值、方差、通道能量）做成在线探针，偏移超阈值即触发步数上调或切回 DDIM，而不是等用户看到色块才告警。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-52\">五十二 · 组合选型的三个工程约束</h3>\n<p>约束一：<strong>CFG 批合并与步数的耦合</strong>。整流流常配 CFG 批合并把条件与非条件前向拼成一个 batch 摊薄开销，但 CFG 引导系数在少步下过大会引起过饱和与色彩崩坏，需按步数重调引导强度。选型时把“步数-引导系数”作为联合参数标定，而不是各自独立调；8 步配置下的最优引导强度通常低于 20 步配置，直接沿用旧值是最常见的画质事故来源。</p>\n<p>约束二：<strong>二阶积分的批合并前提</strong>。中点法每步两次前向，若不加批合并，单图时延反而高于 Euler 大步长配置。选型动作是：切中点法之前先确认批合并已生效、batch 内条件与非条件已拼好，否则两次前向的代价无法被摊薄，二阶的精度收益被时延吃掉。</p>\n<p>约束三：<strong>量化叠加的兼容性</strong>。整流流主体 GEMM 可叠 FP8/NVFP4，但速度场回归对数值精度敏感，尤其在中点法的半步预测上，低精度半步误差会被校正项放大。选型时把量化档位与积分阶数作为二维网格实测：Euler 单步对量化容忍度高，中点法建议主体 GEMM 保持较高精度档或对半步预测单独走高位宽路径。这条与量化条目共享读者，此处只给结论：<strong>二阶积分与激进量化的组合需要单独验证，不能默认继承一阶配置</strong>。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-53\">五十三 · 适用条件的形式化与规模上限</h3>\n<p>把适用条件写成可执行的判据，而不是形容词。设目标分布的条件复杂度为 $c$（可用提示词长度、实体数、文字区域占比做代理），步数预算为 $N$，则整流流的适用域近似为：</p>\n<div class=\"formula\">$$\\text{适用}:\\quad N\\ge N_{\\min}(c),\\qquad N_{\\min}(c)\\approx N_0+\\alpha\\,c$$</div>\n<p>其中 $N_0$ 是简单条件下的下限（经验落在 4–8 步区间），$\\alpha$ 是复杂度对步数的边际需求。$c$ 越大，直线假设越不成立，$N_{\\min}$ 越高；当 $N_{\\min}$ 超过你的 SLO 步数预算时，整流流单独使用不再满足画质，必须叠加蒸馏或回退 DDIM。规模上限同理：超高分辨率与强文本约束下需更多步或蒸馏补偿，这不是算法缺陷而是直线假设的边界，选型时应把这条写进容量规划的分辨率-步数对照表，而不是在事故后临时加步。</p>\n<p>最终落到一个工程判断：同族算法的选择不是静态标签，而是<strong>随负载分布漂移的动态策略</strong>。把 Euler/中点、步数、CFG 强度、量化档位做成可按请求特征路由的配置矩阵，用在线探针监控末端 latent 偏移与细节丢失率，触发降级或升级。整流流在这个矩阵里是默认主干，一致性蒸馏是极低时延分支，DDIM 是画质回退分支——三条路径共享同一套 latent 缓存与 VAE 解码后端，切换成本只在采样循环内部，这才是把选型做成系统能力而非一次性决策的方式。</p>\n\n<h3 id=\"alg-rectified-flow-sampler-sec-54\">五十四 · 同族算法选型：整流流、DDIM 与一致性模型的边界判据</h3>\n<p>整流流不是无条件占优的选项，它与 DDIM、一致性模型构成一条按“路径形状—教师依赖—步数预算”排序的谱系。DDIM 复用预训练 DDPM 的噪声预测网络，scheduler 与模型绑定，换模型即换调度，跨模型复用 scheduler 这条工程诉求在它身上不成立；整流流用统一速度场参数化，训练期把路径重参数化为直线插值，scheduler 因此可跨模型搬运。一致性模型走的是另一条路：靠蒸馏把多步压成一步，必须依赖教师模型产出轨迹对，蒸馏失败即整体失效。判据可写成一条选型不等式：若目标步数 $K\\le 4$ 且允许离线蒸馏，选一致性模型；若 $4\\le K\\le 8$ 且要求 scheduler 可移植，选整流流；若已有 DDPM 权重且不愿重训，只能留在 DDIM。三者的单步代价也不同：Euler 一次前向，中点法两次前向，一致性模型一次前向但需教师侧离线成本。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>路径形状</th><th>教师依赖</th><th>典型步数</th><th>scheduler 复用</th><th>主要失效条件</th></tr></thead><tbody><tr><td>DDIM</td><td>弯曲</td><td>无（复用 DDPM 权重）</td><td>20 步以上</td><td>绑定模型</td><td>步数下降画质崩</td></tr><tr><td>整流流</td><td>直线插值</td><td>无</td><td>4–8 步</td><td>跨模型可复用</td><td>多物体/文字细节丢失</td></tr><tr><td>一致性模型</td><td>蒸馏轨迹</td><td>需教师</td><td>1–4 步</td><td>弱</td><td>蒸馏覆盖不足即失真</td></tr></tbody></table>\n<p>失效条件要按场景分档看。直线假设在单主体、弱文本约束的图上成立得好，20 步压到 8 步画质稳定；但在多物体共存与文字渲染场景，速度场沿直线恒定的前提被破坏，少步直接丢细节、结构错位，此时要么回退到更多步，要么叠加少步蒸馏补偿，二者都增加系统代价——前者线性抬高时延，后者引入离线训练开销。CFG 是另一个隐性边界：引导系数在少步下过大会引起过饱和与色彩崩坏，需按步数重调强度，这意味着 scheduler 跨模型复用时不能原样搬运 CFG 配置，必须随步数预算重新标定，否则“可复用”只在速度场层面成立、在引导层面失效。</p>\n<p>系统代价的权衡落在每步开销与步数的乘积上。Euler 配置单图时延约为 $K\\cdot c_{\\text{fwd}}$，中点法为 $2K\\cdot c_{\\text{fwd}}$，若不加 CFG 批合并把条件与非条件前向拼成一个 batch 摊薄开销，二阶积分在单图小 batch 下反而比 Euler 大步长更慢，这是中点法最容易被误用的地方。显存侧，latent 与 timestep embedding 缓存按 batch 与分辨率线性增长，批大小在 1–8 间取，量化叠加 FP8/NVFP4 主体 GEMM 可压权重带宽但压不住激活侧的 latent 缓存。工程判断因此是：优先 Euler 配 8 步与 CFG 批合并拿吞吐，仅在细节崩坏时局部换中点法并同步放大 batch，让两次前向摊在同一批请求上，而不是让单图独自承担翻倍时延。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2022 · 特征缓存与注意力稀疏</td></tr><tr><td>解决什么</td><td>DDPM/DDIM 的采样轨迹弯曲，少步离散化误差大，步数一降画质就崩，且 scheduler 与模型绑定难以跨模型复…</td></tr><tr><td>一句话机制</td><td>用 rectified flow 把概率路径拉直成直线插值，训练速度场沿直线恒定，推理用 Euler/中点法大步长积分…</td></tr><tr><td>代价与失效</td><td>直线假设在复杂条件（多物体、文字）下不严格成立，少步仍会丢细节；二阶积分需两次前向，单步成本翻倍，需权衡步数与每步开销</td></tr><tr><td>后继</td><td>整流流匹配采样器</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-rectified-flow-sampler · 共 8 个片段</p>\n";break;}}})();
